const a={"les-n3-u15-01":{pedagogical_framework:{what:{summary:"Kausalitas Emosional, Syukur & Dampak Kegagalan (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜かわりに, どんなに / いくら〜ても, 〜にとって, 〜というN, 〜というと / といえば / といったら dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜かわりに dan どんなに / いくら〜ても dalam percakapan kerja wajar.",targetPatterns:["〜かわりに (sebagai gantinya / sebagai imbalannya)","どんなに / いくら〜ても (betapapun ... / seberapa pun ... tetap saja)","〜にとって (bagi ... / menurut sudut pandang ...)","〜というN (N yang bernama ... / N yang disebut ...)","〜というと / といえば / といったら (berbicara soal ... / kalau bicara tentang ...)"],coreVocabSample:["ぐん","ぐん","ぐんたい","けい","けいい","けいき","けいこう","けいじ"]},sensei_context:{sceneIntro:"Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜かわりに dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kausalitas Emosional, Syukur & Dampak Kegagalan",etiquette:"Awali evaluasi sukses dengan mengucapkan syukur atas kerja keras seluruh tim menggunakan okagede.",taboos:"Jangan menggunakan 〜sei de untuk menuding rekan kerja perseorangan secara terbuka di depan umum."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜かわりに",moraNote:"Ucapkan o-ka-ge-de dengan nada hangat dan ramah, serta sei-de dengan nada serius terukur.",soundTip:"Ucapkan 〜かわりに dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜かわりに",caseScenario:"Menggunakan 〜かわりに tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜かわりに.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜かわりに sesuai kaidah.",explanation:"Kaidah koneksi 〜かわりに: V/Adj plain / N + の + かわりに."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kausalitas Emosional, Syukur & Dampak Kegagalan (Fondasi & Pemahaman Pola)",setting:"Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf.",narrative:"Budi dan Sakura berkoordinasi mengenai alur operasional kerja menggunakan pola 〜かわりに."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"ブディさん、軍の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、軍の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, gun no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai tentara, pasukan, militer; kubu / regu? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Sakuraさん！ 父が来られないかわりに、兄が来ました。。",furigana:"はい、Sakuraさん！ 父が来られないかわりに、兄が来ました。。",romaji:"Hai, Sakura-san! かわりに de susumete imasu.",idText:"Ya, Sakura! Sebagai pengganti ayah yang tidak bisa datang, kakak yang datang.."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"なるほど。どんなに頑張っても、間に合わないと思う。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。どんなに頑張っても、間に合わないと思う。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Betapapun keras berusaha, sepertinya tidak akan sempat.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01343",word:"軍",reading:"ぐん",romaji:"gun",meaning:"tentara, pasukan, militer; kubu / regu",pos:"noun",nuance:"Bermakna organisasi militer, bala tentara, atau angkatan perang (seperti 日本軍/tentara Jepang, 空軍/angkatan udara). Namun, dalam kompetisi atau olahraga (seperti bisbol atau kuis), kata ini juga dipakai untuk membedakan regu atau kubu (misal: 白軍/tim putih, 赤軍/tim merah, 一軍/tim inti, 二軍/tim lapis kedua).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"軍【ぐん】を 確認【かくにん】します。",furigana:"軍を 確認します。",romaji:"gun o kakunin shimasu.",idText:"Memeriksa tentara, pasukan, militer; kubu / regu."}},{id:"vg-n3-01344",word:"郡",reading:"ぐん",romaji:"gun",meaning:"distrik, kabupaten (satuan wilayah pedesaan di Jepang)",pos:"noun",nuance:"Pembagian wilayah administratif di bawah tingkat prefektur (県/ken) di Jepang yang menaungi kota kecil (町/chou, machi) atau desa (村/mura), bukan di bawah kota besar (市/shi). Secara praktis sekarang sering berfungsi sebagai penanda alamat pos untuk wilayah non-perkotaan. Berbeda dengan 市 (shi) yang merupakan kotamadya/kota otonom.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"郡【ぐん】を 確認【かくにん】します。",furigana:"郡を 確認します。",romaji:"gun o kakunin shimasu.",idText:"Memeriksa distrik, kabupaten (satuan wilayah pedesaan di Jepang)."}},{id:"vg-n3-01345",word:"軍隊",reading:"ぐんたい",romaji:"guntai",meaning:"tentara, angkatan bersenjata, militer",pos:"noun",nuance:"Merujuk secara formal pada kesatuan organisasi militer/angkatan bersenjata suatu negara yang bertugas mempertahankan kedaulatan atau bertempur. Perlu diperhatikan bahwa secara konstitusional (Pasal 9), Jepang secara resmi menyebut pasukannya sebagai 自衛隊 (Jieitai / Pasukan Bela Diri), bukan 軍隊 (guntai), meskipun dalam pembicaraan umum tentang negara lain atau sejarah kata 軍隊 sangat lazim digunakan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"軍隊【ぐんたい】を 確認【かくにん】します。",furigana:"軍隊を 確認します。",romaji:"guntai o kakunin shimasu.",idText:"Memeriksa tentara, angkatan bersenjata, militer."}},{id:"vg-n3-01347",word:"計",reading:"けい",romaji:"kei",meaning:"total, jumlah keseluruhan; rencana, siasat",pos:"noun",nuance:"Sering diletakkan sebelum atau sesudah angka untuk menyatakan jumlah total keseluruhan (contoh: 計50名/total 50 orang, 合計/total gabungan). Selain itu, sebagai kata benda tunggal juga bermakna muslihat/siasat/rencana (seperti pepatah 一年の計は元旦にあり - rencana setahun bermula di hari tahun baru), atau sebagai sufiks penunjuk instrumen pengukur (体温計/termometer, 時計/jam tangan).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"計【けい】を 確認【かくにん】します。",furigana:"計を 確認します。",romaji:"kei o kakunin shimasu.",idText:"Memeriksa total, jumlah keseluruhan; rencana, siasat."}},{id:"vg-n3-01348",word:"敬意",reading:"けいい",romaji:"keii",meaning:"rasa hormat, respek, penghormatan",pos:"noun",nuance:"Rasa hormat dan penghargaan tulus dari lubuk hati terhadap kepribadian, prestasi, atau kedudukan seseorang. Pola yang sangat umum dipakai adalah 「〜に敬意を払う」 (menaruh rasa hormat / menghormati...) atau 「〜に敬意を表する」 (menyatakan rasa hormat). Berbeda dengan 礼儀 (reigi) yang merujuk pada tata krama lahiriah/sopan santun perilaku.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"敬意【けいい】を 確認【かくにん】します。",furigana:"敬意を 確認します。",romaji:"keii o kakunin shimasu.",idText:"Memeriksa rasa hormat, respek, penghormatan."}},{id:"vg-n3-01350",word:"景気",reading:"けいき",romaji:"keiki",meaning:"kondisi perekonomian, situasi pasar, iklim bisnis",pos:"noun",nuance:"Menyatakan pasang surutnya aktivitas ekonomi secara menyeluruh. Frasa yang sangat khas antara lain 『景気がいい／上向く』 (ekonomi bergairah/membaik), 『景気が悪い／後退する』 (ekonomi lesu/memburuk), dan 不景気 (fukeiki - resesi). Berbeda dengan 経済 (keizai) yang merujuk pada ilmu ekonomi atau sistem perekonomian secara makro, 景気 lebih ke arah suasana gairah atau lesunya perputaran uang dan jual beli di pasar.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"景気【けいき】を 確認【かくにん】します。",furigana:"景気を 確認します。",romaji:"keiki o kakunin shimasu.",idText:"Memeriksa kondisi perekonomian, situasi pasar, iklim bisnis."}},{id:"vg-n3-01351",word:"傾向",reading:"けいこう",romaji:"keikou",meaning:"kecenderungan, tren, tendensi",pos:"noun",nuance:"Arah pergerakan umum atau pola perilaku yang cenderung mengarah ke satu sifat/arah tertentu berdasarkan data atau pengamatan (sering digunakan dalam pola 『〜の傾向がある』 yang berarti 'cenderung...'). Sering muncul dalam teks analitis, statistik, dan ujian JLPT N3/N2 untuk mendeskripsikan tren sosial atau fenomena sains.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"傾向【けいこう】を 確認【かくにん】します。",furigana:"傾向を 確認します。",romaji:"keikou o kakunin shimasu.",idText:"Memeriksa kecenderungan, tren, tendensi."}},{id:"vg-n3-01355",word:"刑事",reading:"けいじ",romaji:"keiji",meaning:"detektif polisi, reserse; perkara pidana",pos:"noun",nuance:"Memiliki dua makna utama: 1) Anggota kepolisian divisi investigasi kriminal berpakaian preman yang menangani kasus kejahatan (detektif/reserse, sering dipanggil デカ/deka dalam bahasa gaul); 2) Istilah hukum pidana (lawan dari 民事/minji - perdata), misalnya 刑事事件 (perkara pidana) atau 刑事裁判 (peradilan pidana).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"刑事【けいじ】を 確認【かくにん】します。",furigana:"刑事を 確認します。",romaji:"keiji o kakunin shimasu.",idText:"Memeriksa detektif polisi, reserse; perkara pidana."}}],explanations:[{id:"exp-1",grammarId:"gn3-00025",title:"Pola: 〜かわりに",formula:"V/Adj plain / N + の + かわりに",meaning:"sebagai gantinya / sebagai imbalannya",nuanceNotes:"〜かわりに menyatakan penggantian atau pertukaran: melakukan X sebagai ganti atau imbalan dari Y.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜かわりに",idText:"sebagai gantinya / sebagai imbalannya"}],examples:[{jp:"父が来られないかわりに、兄が来ました。",romaji:"",idText:"Sebagai pengganti ayah yang tidak bisa datang, kakak yang datang."},{jp:"手伝ってあげるかわりに、夕食をおごってよ。",romaji:"",idText:"Sebagai imbalan sudah dibantu, traktir makan malam dong."}]},{id:"exp-2",grammarId:"gn3-00026",title:"Pola: どんなに / いくら〜ても",formula:"どんなに / いくら + V/Adj + ても",meaning:"betapapun ... / seberapa pun ... tetap saja",nuanceNotes:"どんなに / いくら〜ても menyatakan bahwa tidak peduli seberapa besar tingkat kondisi tertentu, hasilnya tetap tidak berubah.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"どんなに / いくら〜ても",idText:"betapapun ... / seberapa pun ... tetap saja"}],examples:[{jp:"どんなに頑張っても、間に合わないと思う。",romaji:"",idText:"Betapapun keras berusaha, sepertinya tidak akan sempat."},{jp:"いくら説明しても、分かってくれない。",romaji:"",idText:"Seberapa pun dijelaskan, dia tidak mau mengerti."}]},{id:"exp-3",grammarId:"gn3-00050",title:"Pola: 〜にとって",formula:"N + にとって",meaning:"bagi ... / menurut sudut pandang ...",nuanceNotes:'〜にとって menandai perspektif atau sudut pandang seseorang/sesuatu: "bagi", "dari sudut pandang".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜にとって",idText:"bagi ... / menurut sudut pandang ..."}],examples:[{jp:"子どもにとって、遊ぶことは学ぶことだ。",romaji:"",idText:"Bagi anak-anak, bermain adalah belajar."},{jp:"私にとって、家族が一番大切です。",romaji:"",idText:"Bagi saya, keluarga adalah yang paling penting."}]},{id:"exp-4",grammarId:"gn3-00062",title:"Pola: 〜というN",formula:"「...」 + という + N",meaning:"N yang bernama ... / N yang disebut ...",nuanceNotes:'〜というN menghubungkan klausa penjelas dengan nomina: "N yang bernama", "N yang disebut", "N berupa".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜というN",idText:"N yang bernama ... / N yang disebut ..."}],examples:[{jp:"「侍」という言葉の意味を教えてください。",romaji:"",idText:'Tolong ajari saya arti kata "samurai".'},{jp:"田中という人が来ています。",romaji:"",idText:"Ada orang bernama Tanaka yang datang."}]},{id:"exp-5",grammarId:"gn3-00065",title:"Pola: 〜というと / といえば / といったら",formula:"N / 「...」 + というと / といえば / といったら",meaning:"berbicara soal ... / kalau bicara tentang ...",nuanceNotes:"〜といえば dan bentuk sejenisnya digunakan untuk menghubungkan topik yang baru disebut dengan asosiasi atau respons tertentu.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜というと / といえば / といったら",idText:"berbicara soal ... / kalau bicara tentang ..."}],examples:[{jp:"日本といえば、やはり富士山ですね。",romaji:"",idText:"Kalau bicara tentang Jepang, ya Gunung Fuji."},{jp:"夏というと、お祭りを思い出します。",romaji:"",idText:"Berbicara soal musim panas, saya teringat festival."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "軍"?',sentencePrompt:'Makna kata "軍" (ぐん) dalam situasi kerja ini adalah:',options:["tentara, pasukan, militer; kubu / regu","distrik, kabupaten (satuan wilayah pedesaan di Jepang)","tentara, angkatan bersenjata, militer","total, jumlah keseluruhan; rencana, siasat"],correctAnswer:"tentara, pasukan, militer; kubu / regu",explanation:'Makna yang tepat untuk "軍" adalah "tentara, pasukan, militer; kubu / regu".',diagnosticFeedback:{"distrik, kabupaten (satuan wilayah pedesaan di Jepang)":'Salah: Pilihan "distrik, kabupaten (satuan wilayah pedesaan di Jepang)" adalah makna dari kata "郡" (ぐん), bukan arti kata "軍".',"tentara, angkatan bersenjata, militer":'Salah: Pilihan "tentara, angkatan bersenjata, militer" adalah makna dari kata "軍隊" (ぐんたい), bukan arti kata "軍".',"total, jumlah keseluruhan; rencana, siasat":'Salah: Pilihan "total, jumlah keseluruhan; rencana, siasat" adalah makna dari kata "計" (けい), bukan arti kata "軍".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"父が来られない（　　）、兄が来ました。",options:["かわりに","どんなに / いくら〜ても","にとって","つまり"],correctAnswer:"かわりに",explanation:'Pola 〜かわりに bermakna "sebagai gantinya / sebagai imbalannya". Kalimat lengkap: "父が来られないかわりに、兄が来ました。".',diagnosticFeedback:{"どんなに / いくら〜ても":'Salah: Pola "どんなに / いくら〜ても" bermakna "betapapun ... / seberapa pun ... tetap saja", yang tidak sesuai konteks kalimat ini.',にとって:'Salah: Pola "にとって" bermakna "bagi ... / menurut sudut pandang ...", yang tidak sesuai konteks kalimat ini.',つまり:'Salah: Pola "つまり" bermakna "maksudnya ... / dengan kata lain ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜かわりに secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["手伝ってあげるかわりに、夕食をおごってよ。","手伝ってあげるかわりにでした、夕食をおごってよ。","どんなに頑張っても、間に合わないと思う。","「武士道」というのは、侍の倫理規範のことです。"],correctAnswer:"手伝ってあげるかわりに、夕食をおごってよ。",explanation:'Kalimat yang benar dan alami adalah "手伝ってあげるかわりに、夕食をおごってよ。" (Sebagai imbalan sudah dibantu, traktir makan malam dong.).',diagnosticFeedback:{"手伝ってあげるかわりにでした、夕食をおごってよ。":"Jebakan Konjugasi: Pola 〜かわりに membutuhkan aturan sambung (V/Adj plain / N + の + かわりに), bukan bentuk ini.","どんなに頑張っても、間に合わないと思う。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (どんなに / いくら〜ても: betapapun ... / seberapa pun ... tetap saja), bukan kaidah 〜かわりに.","「武士道」というのは、侍の倫理規範のことです。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜かわりに secara tepat (sebagai gantinya / sebagai imbalannya)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["どんなに頑 張っても、 間に合わないと 思う。","張っても、 どんなに頑 間に合わないと 思う。","どんなに頑 間に合わないと 張っても、 思う。","思う。 どんなに頑 張っても、 間に合わないと"],correctAnswer:"どんなに頑 張っても、 間に合わないと 思う。",explanation:'Susunan yang benar: "どんなに頑 張っても、 間に合わないと 思う。" (Betapapun keras berusaha, sepertinya tidak akan sempat.).',diagnosticFeedback:{"張っても、 どんなに頑 間に合わないと 思う。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","どんなに頑 間に合わないと 張っても、 思う。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","思う。 どんなに頑 張っても、 間に合わないと":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["どんなに頑","張っても、","間に合わないと","思う。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf.", saat Sakura menyampaikan arahan: 「なるほど。どんなに頑張っても、間に合わないと思う。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜かわりに dan どんなに / いくら〜ても dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜かわりに!",modelAnswer:"はい、Sakuraさん！ 父が来られないかわりに、兄が来ました。。",modelAnswerId:"Ya, Sakura! Sebagai pengganti ayah yang tidak bisa datang, kakak yang datang..",culturalEtiquette:"Awali evaluasi sukses dengan mengucapkan syukur atas kerja keras seluruh tim menggunakan okagede.",skillUnlocked:["Menguasai formulasi pola 〜かわりに","Mampu menerapkan prinsip koordinasi komunikasi kerja Kausalitas Emosional, Syukur & Dampak Kegagalan"]},pocket_summary:{keyFormula:"〜かわりに (sebagai gantinya / sebagai imbalannya)",coreWords:["軍【ぐん】 (tentara, pasukan, militer; kubu / regu)","郡【ぐん】 (distrik, kabupaten (satuan wilayah pedesaan di Jepang))","軍隊【ぐんたい】 (tentara, angkatan bersenjata, militer)","計【けい】 (total, jumlah keseluruhan; rencana, siasat)"],coreWarning:"Jangan menggunakan 〜sei de untuk menuding rekan kerja perseorangan secara terbuka di depan umum.",quickDialogue:"A: ブディさん、軍の 状況【じょうきょう】は どうです... → B: はい、Sakuraさん！ 父が来られないかわりに、..."}},"les-n3-u15-02":{pedagogical_framework:{what:{summary:"Kausalitas Emosional, Syukur & Dampak Kegagalan (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜といっても, 〜ように（目的）, 〜ところが, 〜ところで dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜といっても dan 〜ように（目的） secara mandiri.",targetPatterns:["〜といっても (meskipun disebut ... / bukan berarti ...)","〜ように（目的） (agar ... / supaya ...)","〜ところが (namun ternyata / tapi sebaliknya)","〜ところで (ngomong-ngomong / omong-omong)"],coreVocabSample:["ざいさん","さいしゅう","さいちゅう","さいのう","さかい","さかり","さく","さくもつ"]},sensei_context:{sceneIntro:"Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜といっても dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kausalitas Emosional, Syukur & Dampak Kegagalan",etiquette:"Awali evaluasi sukses dengan mengucapkan syukur atas kerja keras seluruh tim menggunakan okagede.",taboos:"Jangan menggunakan 〜sei de untuk menuding rekan kerja perseorangan secara terbuka di depan umum."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜といっても",moraNote:"Ucapkan o-ka-ge-de dengan nada hangat dan ramah, serta sei-de dengan nada serius terukur.",soundTip:"Ucapkan 〜といっても dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜といっても",caseScenario:"Menggunakan 〜といっても tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜といっても.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜といっても sesuai kaidah.",explanation:"Kaidah koneksi 〜といっても: N / 「...」 + といっても."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kausalitas Emosional, Syukur & Dampak Kegagalan (Produksi Aktif & Aplikasi Nyata)",setting:"Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf.",narrative:"Budi dan Sakura berkoordinasi mengenai alur operasional kerja menggunakan pola 〜といっても."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"ブディさん、財産の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、財産の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, zaisan no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai harta kekayaan, aset, kepemilikan materi bernilai? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Sakuraさん！ 経験者といっても、まだ半年しかない。。",furigana:"はい、Sakuraさん！ 経験者といっても、まだ半年しかない。。",romaji:"Hai, Sakura-san! といっても de susumete imasu.",idText:"Ya, Sakura! Meskipun disebut berpengalaman, baru setengah tahun.."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"なるほど。忘れないように、メモをとった。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。忘れないように、メモをとった。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Mencatat agar tidak lupa.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01462",word:"財産",reading:"ざいさん",romaji:"zaisan",meaning:"harta kekayaan, aset, kepemilikan materi bernilai",pos:"noun",nuance:"Seluruh aset kepemilikan benda bergerak, tidak bergerak, maupun nilai uang dari individu atau korporasi (財産分与 / pembagian harta gono-gini, 財産を残す / mewariskan harta). Secara kiasan juga digunakan untuk hal non-materi bernilai luhur seperti persahabatan atau pengalaman berharga seumur hidup.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"財産【ざいさん】を 確認【かくにん】します。",furigana:"財産を 確認します。",romaji:"zaisan o kakunin shimasu.",idText:"Memeriksa harta kekayaan, aset, kepemilikan materi bernilai."}},{id:"vg-n3-01463",word:"最終",reading:"さいしゅう",romaji:"saishuu",meaning:"terakhir, putaran akhir, final, tahap penghabisan",pos:"noun",nuance:"Tahapan urutan paling akhir dari suatu jadwal, rangkaian babak seleksi, atau perjalanan (seperti: 最終電車 / 最終便 - kereta/penerbangan terakhir, 最終面接 - wawancara kerja tahap akhir, 最終決定 - keputusan final). Berbeda dengan 最後 (saigo) yang dapat merujuk pada fisik barisan paling belakang atau ujung akhir waktu.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"最終【さいしゅう】を 確認【かくにん】します。",furigana:"最終を 確認します。",romaji:"saishuu o kakunin shimasu.",idText:"Memeriksa terakhir, putaran akhir, final, tahap penghabisan."}},{id:"vg-n3-01464",word:"最中",reading:"さいちゅう",romaji:"saichuu",meaning:"di tengah-tengah, tepat saat sedang berlangsung",pos:"noun",nuance:"Tata bahasa penting N3: 〜最中に / 〜最中だ. Menandakan suatu tindakan aktif yang sedang intens berlangsung pada puncaknya, lalu mendadak disela oleh kejadian tak terduga (contoh: 食事の最中に / tepat saat sedang makan). Catatan: bila dibaca 'monaka', merujuk pada camilan tradisional jepang berupa wafer berisi pasta kacang azuki.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"最中【さいちゅう】を 確認【かくにん】します。",furigana:"最中を 確認します。",romaji:"saichuu o kakunin shimasu.",idText:"Memeriksa di tengah-tengah, tepat saat sedang berlangsung."}},{id:"vg-n3-01466",word:"才能",reading:"さいのう",romaji:"sainou",meaning:"bakat, talenta, kemampuan alami istimewa",pos:"noun",nuance:"Bakat atau potensi pembawaan sejak lahir yang luar biasa dalam bidang seni, olahraga, atau pemikiran (才能がある / berbakat, 才能を発揮する / mengeluarkan bakat). Berbeda dengan 能力 (nouryoku) yang mencakup kapasitas keahlian umum termasuk hasil dari latihan keras.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"才能【さいのう】を 確認【かくにん】します。",furigana:"才能を 確認します。",romaji:"sainou o kakunin shimasu.",idText:"Memeriksa bakat, talenta, kemampuan alami istimewa."}},{id:"vg-n3-01470",word:"境",reading:"さかい",romaji:"sakai",meaning:"perbatasan, batas garis pemisah; titik peralihan",pos:"noun",nuance:"Garis fisik pemisah antara dua area atau tanah (contoh: 隣の家との境 / batas dengan rumah tetangga), atau batas waktu ketika suatu situasi berbalik secara signifikan (contoh: 30歳を境に体力が落ちた / sejak melewati usia 30 tahun daya tahan tubuh menurun). Sering juga dipakai dalam bentuk 境目 (sakaime).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"境【さかい】を 確認【かくにん】します。",furigana:"境を 確認します。",romaji:"sakai o kakunin shimasu.",idText:"Memeriksa perbatasan, batas garis pemisah; titik peralihan."}},{id:"vg-n3-01472",word:"盛り",reading:"さかり",romaji:"sakari",meaning:"masa puncak, masa kejayaan, masa mekar penuh, puncak keemasan",pos:"noun",nuance:"Periode atau kondisi ketika sesuatu sedang berada pada daya puncaknya, paling subur, atau paling aktif (contoh: 桜の盛り / puncak mekarnya sakura, 働き盛り / masa keemasan usia produktif berkarya, 食べ盛り / masa kuat-kuatnya anak makan). Catatan: bila dibaca 'mori', artinya porsi sendokan hidangan seperti 大盛り (oomori - porsi besar).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"盛り【さかり】を 確認【かくにん】します。",furigana:"盛りを 確認します。",romaji:"sakari o kakunin shimasu.",idText:"Memeriksa masa puncak, masa kejayaan, masa mekar penuh, puncak keemasan."}},{id:"vg-n3-01475",word:"昨",reading:"さく",romaji:"saku",meaning:"lalu, kemarin (awalan: tahun lalu, kemarin malam)",pos:"noun",nuance:"Prefiks kanji formal yang bermakna 'kemarin' atau 'lalu'. Hampir selalu muncul mengawali kata majemuk penanda waktu dalam konteks resmi dan laporan berita: 昨年 (sakunen - tahun lalu), 昨日 (sakujitsu - kemarin), 昨夜 (sakuya / sakuban - kemarin malam), 昨今 (sakkon - akhir-akhir ini). Lebih formal dibanding 昨日 (kinou) atau 去年 (kyonen).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"昨【さく】を 確認【かくにん】します。",furigana:"昨を 確認します。",romaji:"saku o kakunin shimasu.",idText:"Memeriksa lalu, kemarin (awalan: tahun lalu, kemarin malam)."}},{id:"vg-n3-01476",word:"作物",reading:"さくもつ",romaji:"sakumotsu",meaning:"hasil panen, tanaman pangan, hasil bumi pertanian",pos:"noun",nuance:"Tanaman pangan yang ditanam dan dipanen petani untuk konsumsi manusia atau ternak (seperti beras, sayuran, dan gandum: 農作物 / nousakumotsu). Perhatikan cara bacanya: jika dibaca さくもつ (sakumotsu) artinya tanaman hasil panen, sedangkan jika dibaca さくぶつ (sakubutsu) artinya karya cipta sastra atau seni.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"作物【さくもつ】を 確認【かくにん】します。",furigana:"作物を 確認します。",romaji:"sakumotsu o kakunin shimasu.",idText:"Memeriksa hasil panen, tanaman pangan, hasil bumi pertanian."}}],explanations:[{id:"exp-1",grammarId:"gn3-00066",title:"Pola: 〜といっても",formula:"N / 「...」 + といっても",meaning:"meskipun disebut ... / bukan berarti ...",nuanceNotes:"〜といっても menyatakan bahwa meskipun ada label tertentu, kondisinya tidak sebesar atau seintens yang dibayangkan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜といっても",idText:"meskipun disebut ... / bukan berarti ..."}],examples:[{jp:"経験者といっても、まだ半年しかない。",romaji:"",idText:"Meskipun disebut berpengalaman, baru setengah tahun."},{jp:"旅行といっても、近所をぶらぶらするだけ。",romaji:"",idText:"Meskipun disebut wisata, hanya jalan-jalan di sekitar sini saja."}]},{id:"exp-2",grammarId:"gn3-00071",title:"Pola: 〜ように（目的）",formula:"Vる/ない + ように + V(usaha)",meaning:"agar ... / supaya ...",nuanceNotes:"〜ように（目的） menyatakan tujuan agar kondisi tertentu terwujud. Berbeda dari ために: ように untuk kondisi/keadaan, ために untuk tindakan langsung.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ように（目的）",idText:"agar ... / supaya ..."}],examples:[{jp:"忘れないように、メモをとった。",romaji:"",idText:"Mencatat agar tidak lupa."},{jp:"合格できるように、毎日勉強しています。",romaji:"",idText:"Belajar setiap hari agar bisa lulus."}]},{id:"exp-3",grammarId:"gn3-00086",title:"Pola: 〜ところが",formula:"文1。ところが、文2。",meaning:"namun ternyata / tapi sebaliknya",nuanceNotes:"〜ところが menghubungkan dua kalimat yang hasilnya berlawanan dari yang diharapkan. Menekankan kejutan atau ketidaksesuaian.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ところが",idText:"namun ternyata / tapi sebaliknya"}],examples:[{jp:"簡単だと思っていた。ところが、とても難しかった。",romaji:"",idText:"Saya pikir mudah. Namun ternyata sangat sulit."},{jp:"急いで行った。ところが、店はもう閉まっていた。",romaji:"",idText:"Pergi terburu-buru. Tapi ternyata toko sudah tutup."}]},{id:"exp-4",grammarId:"gn3-00087",title:"Pola: 〜ところで",formula:"文1。ところで、文2。",meaning:"ngomong-ngomong / omong-omong",nuanceNotes:'〜ところで digunakan untuk mengalihkan topik pembicaraan: "ngomong-ngomong", "omong-omong".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ところで",idText:"ngomong-ngomong / omong-omong"}],examples:[{jp:"それはよかった。ところで、来週の予定は？",romaji:"",idText:"Itu bagus. Ngomong-ngomong, rencana minggu depan?"},{jp:"ところで、もう昼食は食べましたか？",romaji:"",idText:"Omong-omong, sudah makan siang?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "財産"?',sentencePrompt:'Makna kata "財産" (ざいさん) dalam situasi kerja ini adalah:',options:["harta kekayaan, aset, kepemilikan materi bernilai","terakhir, putaran akhir, final, tahap penghabisan","di tengah-tengah, tepat saat sedang berlangsung","bakat, talenta, kemampuan alami istimewa"],correctAnswer:"harta kekayaan, aset, kepemilikan materi bernilai",explanation:'Makna yang tepat untuk "財産" adalah "harta kekayaan, aset, kepemilikan materi bernilai".',diagnosticFeedback:{"terakhir, putaran akhir, final, tahap penghabisan":'Salah: Pilihan "terakhir, putaran akhir, final, tahap penghabisan" adalah makna dari kata "最終" (さいしゅう), bukan arti kata "財産".',"di tengah-tengah, tepat saat sedang berlangsung":'Salah: Pilihan "di tengah-tengah, tepat saat sedang berlangsung" adalah makna dari kata "最中" (さいちゅう), bukan arti kata "財産".',"bakat, talenta, kemampuan alami istimewa":'Salah: Pilihan "bakat, talenta, kemampuan alami istimewa" adalah makna dari kata "才能" (さいのう), bukan arti kata "財産".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"経験者（　　）、まだ半年しかない。",options:["といっても","ように","ところが","つまり"],correctAnswer:"といっても",explanation:'Pola 〜といっても bermakna "meskipun disebut ... / bukan berarti ...". Kalimat lengkap: "経験者といっても、まだ半年しかない。".',diagnosticFeedback:{ように:'Salah: Pola "ように" bermakna "agar ... / supaya ...", yang tidak sesuai konteks kalimat ini.',ところが:'Salah: Pola "ところが" bermakna "namun ternyata / tapi sebaliknya", yang tidak sesuai konteks kalimat ini.',つまり:'Salah: Pola "つまり" bermakna "maksudnya ... / dengan kata lain ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜といっても secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["旅行といっても、近所をぶらぶらするだけ。","旅行といってもでした、近所をぶらぶらするだけ。","忘れないように、メモをとった。","「武士道」というのは、侍の倫理規範のことです。"],correctAnswer:"旅行といっても、近所をぶらぶらするだけ。",explanation:'Kalimat yang benar dan alami adalah "旅行といっても、近所をぶらぶらするだけ。" (Meskipun disebut wisata, hanya jalan-jalan di sekitar sini saja.).',diagnosticFeedback:{"旅行といってもでした、近所をぶらぶらするだけ。":"Jebakan Konjugasi: Pola 〜といっても membutuhkan aturan sambung (N / 「...」 + といっても), bukan bentuk ini.","忘れないように、メモをとった。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ように（目的）: agar ... / supaya ...), bukan kaidah 〜といっても.","「武士道」というのは、侍の倫理規範のことです。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜といっても secara tepat (meskipun disebut ... / bukan berarti ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["忘れないように 、 メモをとった 。","、 忘れないように メモをとった 。","忘れないように メモをとった 、 。","。 忘れないように 、 メモをとった"],correctAnswer:"忘れないように 、 メモをとった 。",explanation:'Susunan yang benar: "忘れないように 、 メモをとった 。" (Mencatat agar tidak lupa.).',diagnosticFeedback:{"、 忘れないように メモをとった 。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","忘れないように メモをとった 、 。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","。 忘れないように 、 メモをとった":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["忘れないように","、","メモをとった","。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf.", saat Sakura menyampaikan arahan: 「なるほど。忘れないように、メモをとった。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜といっても dan 〜ように（目的） secara mandiri.",situation:"Situasi komunikasi profesional di Pertemuan refleksi akhir proyek pemasangan lini mesin otomatis bersama seluruh staf.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜といっても!",modelAnswer:"はい、Sakuraさん！ 経験者といっても、まだ半年しかない。。",modelAnswerId:"Ya, Sakura! Meskipun disebut berpengalaman, baru setengah tahun..",culturalEtiquette:"Awali evaluasi sukses dengan mengucapkan syukur atas kerja keras seluruh tim menggunakan okagede.",skillUnlocked:["Menguasai formulasi pola 〜といっても","Mampu menerapkan prinsip koordinasi komunikasi kerja Kausalitas Emosional, Syukur & Dampak Kegagalan"]},pocket_summary:{keyFormula:"〜といっても (meskipun disebut ... / bukan berarti ...)",coreWords:["財産【ざいさん】 (harta kekayaan, aset, kepemilikan materi bernilai)","最終【さいしゅう】 (terakhir, putaran akhir, final, tahap penghabisan)","最中【さいちゅう】 (di tengah-tengah, tepat saat sedang berlangsung)","才能【さいのう】 (bakat, talenta, kemampuan alami istimewa)"],coreWarning:"Jangan menggunakan 〜sei de untuk menuding rekan kerja perseorangan secara terbuka di depan umum.",quickDialogue:"A: ブディさん、財産の 状況【じょうきょう】は どうで... → B: はい、Sakuraさん！ 経験者といっても、まだ半..."}}},n={"les-n3-u16-01":{pedagogical_framework:{what:{summary:"Kontras Paradoks, Ketidaksesuaian & Konsesi (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜つまり, 〜に〜かわって, 〜のこと, 〜てくれと頼まれた / 〜なと言われた, 〜によって dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜つまり dan 〜に〜かわって dalam percakapan kerja wajar.",targetPatterns:["〜つまり (maksudnya ... / dengan kata lain ...)","〜に〜かわって (menggantikan ... / atas nama ...)","〜のこと (tentang ... / hal mengenai ...)","〜てくれと頼まれた / 〜なと言われた (diminta untuk ... / diberitahu jangan ...)","〜によって (tergantung ..., disebabkan oleh ..., berdasarkan ...)"],coreVocabSample:["ゆうこう","ゆうじょう","ゆうびん","ユーモア","ゆか","よあけ","ようき","ようそ"]},sensei_context:{sceneIntro:"Audit berkala operasional pergudangan rantai pasok logistik lintas daerah. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜つまり dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kontras Paradoks, Ketidaksesuaian & Konsesi",etiquette:"Sampaikan evaluasi deviasi secara objektif dengan memaparkan data pembanding yang valid.",taboos:"Hindari memakai 〜kuse ni (padahal / bernada sinis) kepada kolega atau pelanggan kerja."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜つまり",moraNote:"Berikan jeda singkat setelah kata penghubung monono sebelum masuk ke klausa kontras.",soundTip:"Ucapkan 〜つまり dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜つまり",caseScenario:"Menggunakan 〜つまり tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜つまり.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜つまり sesuai kaidah.",explanation:"Kaidah koneksi 〜つまり: 文1。つまり、文2。."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Audit berkala operasional pergudangan rantai pasok logistik lintas daerah.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kontras Paradoks, Ketidaksesuaian & Konsesi (Fondasi & Pemahaman Pola)",setting:"Audit berkala operasional pergudangan rantai pasok logistik lintas daerah.",narrative:"Budi dan Sakura berkoordinasi mengenai alur operasional kerja menggunakan pola 〜つまり."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"ブディさん、友好の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、友好の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, yuukou no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai persahabatan, hubungan baik (antarnegara, antarkota, atau kelompok besar)? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Sakuraさん！ 彼は昨日も一昨日も来なかった。つまり、もう来ないつもりだろう。。",furigana:"はい、Sakuraさん！ 彼は昨日も一昨日も来なかった。つまり、もう来ないつもりだろう。。",romaji:"Hai, Sakura-san! つまり de susumete imasu.",idText:"Ya, Sakura! Dia kemarin dan kemarin lusa tidak datang. Maksudnya, sepertinya dia sudah tidak berniat datang.."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"なるほど。父にかわって、私が挨拶します。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。父にかわって、私が挨拶します。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Menggantikan ayah, saya yang akan menyampaikan sambutan.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01580",word:"友好",reading:"ゆうこう",romaji:"yuukou",meaning:"persahabatan, hubungan baik (antarnegara, antarkota, atau kelompok besar)",pos:"noun",nuance:"Merujuk pada ikatan relasi persahabatan, kerja sama, dan perdamaian yang terjalin antara institusi publik besar seperti dua negara, kota mitra, atau organisasi (contoh: 友好条約 - traktat persahabatan; 友好都市 - kota kembar bersahabat; 日中友好 - persahabatan Jepang-Tiongkok). Berbeda dengan 友情 (yuujou) yang merupakan rasa persahabatan personal antarindividu.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"友好【ゆうこう】を 確認【かくにん】します。",furigana:"友好を 確認します。",romaji:"yuukou o kakunin shimasu.",idText:"Memeriksa persahabatan, hubungan baik (antarnegara, antarkota, atau kelompok besar)."}},{id:"vg-n3-01584",word:"友情",reading:"ゆうじょう",romaji:"yuujou",meaning:"persahabatan, ikatan persahabatan, rasa setia kawan",pos:"noun",nuance:"Perasaan kasih, kepercayaan, dan keakraban mendalam antarindividu yang terjalin sebagai sahabat. Sering dipakai dalam frasa: 友情を深める (mempererat persahabatan), 友情を育む (menumbuhkan ikatan sahabat), serta 友情にひびが入る (persahabatan retak). Berbeda dengan 友好 (yuukou) yang merujuk pada persahabatan resmi antarbangsa/antarkelompok.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"友情【ゆうじょう】を 確認【かくにん】します。",furigana:"友情を 確認します。",romaji:"yuujou o kakunin shimasu.",idText:"Memeriksa persahabatan, ikatan persahabatan, rasa setia kawan."}},{id:"vg-n3-01586",word:"郵便",reading:"ゆうびん",romaji:"yuubin",meaning:"pos, surat-menyurat, layanan pos",pos:"noun",nuance:"Merujuk pada sistem pengiriman surat atau paket pos, ataupun kiriman surat itu sendiri. Sering dipakai dalam bentuk gabungan seperti 郵便局 (kantor pos), 郵便番号 (kode pos), 郵便受け/ポスト (kotak surat), dan 郵便物 (surat/barang pos). Berbeda dengan 宅配便 (takuhaibin) yang merujuk pada jasa kurir atau ekspedisi swasta.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"郵便【ゆうびん】を 確認【かくにん】します。",furigana:"郵便を 確認します。",romaji:"yuubin o kakunin shimasu.",idText:"Memeriksa pos, surat-menyurat, layanan pos."}},{id:"vg-n3-01587",word:"ユーモア",reading:"ユーモア",romaji:"yuumoa",meaning:"humor, rasa humor, kelucuan",pos:"noun",nuance:"Kata serapan dari bahasa Inggris 'humor'. Menunjukkan kecerdasan dalam membuat candaan yang menyenangkan atau sifat jenaka seseorang. Sering dipakai dalam frase ユーモアがある (memiliki selera humor) atau ユーモアを交えて (diselingi humor). Berbeda dengan 冗談 (joudan / lelucon atau bercandaan spesifik) atau お笑い (owarai / hiburan komedi panggung).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ユーモアを 確認【かくにん】します。",furigana:"ユーモアを 確認します。",romaji:"yuumoa o kakunin shimasu.",idText:"Memeriksa humor, rasa humor, kelucuan."}},{id:"vg-n3-01589",word:"床",reading:"ゆか",romaji:"yuka",meaning:"lantai",pos:"noun",nuance:"Merujuk pada permukaan bawah lantai dalam ruangan tempat orang berpijak (bisa lantai kayu, ubin, tatami, dll.). Sering dipadukan dalam kata 床下 (di bawah lantai), 床暖房 (pemanas lantai), 床を拭く (mengepel atau mengelap lantai). Jangan tertukar dengan kanji 床 yang dibaca 'toko' (artinya ranjang atau tempat tidur tradisional).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"床【ゆか】を 確認【かくにん】します。",furigana:"床を 確認します。",romaji:"yuka o kakunin shimasu.",idText:"Memeriksa lantai."}},{id:"vg-n3-01594",word:"夜明け",reading:"よあけ",romaji:"yoake",meaning:"fajar, subuh, dini hari; awal babak baru",pos:"noun",nuance:"Merujuk pada waktu langit malam mulai memudar dan fajar mulai menyingsing sebelum matahari terbit sempurna. Selain arti harfiah waktu, sering digunakan secara metaforis untuk menandakan fajar atau awal era baru (misalnya 新時代の夜明け / fajar era baru). Mirip dengan 明け方 (akegata).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"夜明け【よあけ】を 確認【かくにん】します。",furigana:"夜明けを 確認します。",romaji:"yoake o kakunin shimasu.",idText:"Memeriksa fajar, subuh, dini hari; awal babak baru."}},{id:"vg-n3-01597",word:"容器",reading:"ようき",romaji:"youki",meaning:"wadah, tempat penyimpanan barang/makanan, kontainer",pos:"noun",nuance:"Istilah umum untuk benda yang dibuat khusus untuk menampung atau memuat zat padat, cair, atau gas (seperti botol, toples, kotak plastik tupperware, kaleng). Sering digabung dalam プラスチック容器 (wadah plastik), 耐熱容器 (wadah tahan panas), 密閉容器 (wadah kedap udara). Berbeda dengan 入れ物 (iremono) yang lebih bernada santai sehari-hari.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"容器【ようき】を 確認【かくにん】します。",furigana:"容器を 確認します。",romaji:"youki o kakunin shimasu.",idText:"Memeriksa wadah, tempat penyimpanan barang/makanan, kontainer."}},{id:"vg-n3-01602",word:"要素",reading:"ようそ",romaji:"youso",meaning:"elemen, faktor, unsur pokok",pos:"noun",nuance:"Merujuk pada komponen dasar atau unsur pokok yang membentuk suatu kesatuan, kejadian, atau sistem (contoh: 成功の要素 / faktor penentu keberhasilan, 構成要素 / elemen penyusun). Sering digunakan dalam diskusi analisis, bisnis, sains, dan esai. Mirip dengan 要因 (youin / faktor penyebab).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"要素【ようそ】を 確認【かくにん】します。",furigana:"要素を 確認します。",romaji:"youso o kakunin shimasu.",idText:"Memeriksa elemen, faktor, unsur pokok."}}],explanations:[{id:"exp-1",grammarId:"gn3-00088",title:"Pola: 〜つまり",formula:"文1。つまり、文2。",meaning:"maksudnya ... / dengan kata lain ...",nuanceNotes:'〜つまり digunakan untuk merangkum, menyimpulkan, atau menyederhanakan apa yang telah dikatakan: "maksudnya", "jadi", "dengan kata lain".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜つまり",idText:"maksudnya ... / dengan kata lain ..."}],examples:[{jp:"彼は昨日も一昨日も来なかった。つまり、もう来ないつもりだろう。",romaji:"",idText:"Dia kemarin dan kemarin lusa tidak datang. Maksudnya, sepertinya dia sudah tidak berniat datang."},{jp:"彼女は仕事もやめて、家族とも連絡を絶った。つまり、一人で生きていくつもりなのだ。",romaji:"",idText:"Dia berhenti kerja dan memutus kontak dengan keluarga. Dengan kata lain, dia berniat hidup sendiri."}]},{id:"exp-2",grammarId:"gn3-00094",title:"Pola: 〜に〜かわって",formula:"N + に + かわって",meaning:"menggantikan ... / atas nama ...",nuanceNotes:"〜にかわって menyatakan melakukan sesuatu menggantikan orang lain atau atas nama seseorang.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に〜かわって",idText:"menggantikan ... / atas nama ..."}],examples:[{jp:"父にかわって、私が挨拶します。",romaji:"",idText:"Menggantikan ayah, saya yang akan menyampaikan sambutan."},{jp:"全員にかわってお礼申し上げます。",romaji:"",idText:"Atas nama semua anggota, saya menyampaikan terima kasih."}]},{id:"exp-3",grammarId:"gn3-00096",title:"Pola: 〜のこと",formula:"N + のこと",meaning:"tentang ... / hal mengenai ...",nuanceNotes:'〜のこと digunakan untuk menandai topik pembicaraan yang lebih personal atau mendalam: "hal tentang", "soal".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜のこと",idText:"tentang ... / hal mengenai ..."}],examples:[{jp:"あなたのことが好きです。",romaji:"",idText:"Saya suka kamu."},{jp:"仕事のことで相談があります。",romaji:"",idText:"Saya punya hal yang ingin didiskusikan mengenai pekerjaan."}]},{id:"exp-4",grammarId:"gn3-00101",title:"Pola: 〜てくれと頼まれた / 〜なと言われた",formula:"「〜てくれ」と頼まれた / 「〜な」と言われた",meaning:"diminta untuk ... / diberitahu jangan ...",nuanceNotes:"〜てくれと頼まれた: diminta melakukan sesuatu (kutipan tidak langsung). 〜なと言われた: diberitahu untuk tidak melakukan sesuatu.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てくれと頼まれた / 〜なと言われた",idText:"diminta untuk ... / diberitahu jangan ..."}],examples:[{jp:"手伝ってくれと頼まれた。",romaji:"",idText:"Diminta untuk membantu."},{jp:"無理するなと言われた。",romaji:"",idText:"Diberitahu agar tidak memaksakan diri."}]},{id:"exp-5",grammarId:"gn3-00142",title:"Pola: 〜によって",formula:"N + によって / により",meaning:"tergantung ..., disebabkan oleh ..., berdasarkan ...",nuanceNotes:"〜によって memiliki tiga makna utama: (1) menyatakan penyebab atau cara (disebabkan oleh, dengan cara); (2) menyatakan bahwa sesuatu berbeda tergantung kondisi tertentu; (3) menyatakan pelaku dalam kalimat pasif formal. Versi yang lebih formal adalah 〜により, sering digunakan dalam penulisan resmi.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜によって",idText:"tergantung ..., disebabkan oleh ..., berdasarkan ..."}],examples:[{jp:"国によって、文化が違う。",romaji:"",idText:"Tergantung negaranya, budayanya berbeda."},{jp:"この事故は不注意によって引き起こされた。",romaji:"",idText:"Kecelakaan ini disebabkan oleh kelalaian."},{jp:"この絵はピカソによって描かれた。",romaji:"",idText:"Lukisan ini dibuat oleh Picasso."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "友好"?',sentencePrompt:'Makna kata "友好" (ゆうこう) dalam situasi kerja ini adalah:',options:["persahabatan, hubungan baik (antarnegara, antarkota, atau kelompok besar)","persahabatan, ikatan persahabatan, rasa setia kawan","pos, surat-menyurat, layanan pos","humor, rasa humor, kelucuan"],correctAnswer:"persahabatan, hubungan baik (antarnegara, antarkota, atau kelompok besar)",explanation:'Makna yang tepat untuk "友好" adalah "persahabatan, hubungan baik (antarnegara, antarkota, atau kelompok besar)".',diagnosticFeedback:{"persahabatan, ikatan persahabatan, rasa setia kawan":'Salah: Pilihan "persahabatan, ikatan persahabatan, rasa setia kawan" adalah makna dari kata "友情" (ゆうじょう), bukan arti kata "友好".',"pos, surat-menyurat, layanan pos":'Salah: Pilihan "pos, surat-menyurat, layanan pos" adalah makna dari kata "郵便" (ゆうびん), bukan arti kata "友好".',"humor, rasa humor, kelucuan":'Salah: Pilihan "humor, rasa humor, kelucuan" adalah makna dari kata "ユーモア" (ユーモア), bukan arti kata "友好".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"彼は昨日も一昨日も来なかった。（　　）、もう来ないつもりだろう。",options:["つまり","に〜かわって","のこと","わけではない"],correctAnswer:"つまり",explanation:'Pola 〜つまり bermakna "maksudnya ... / dengan kata lain ...". Kalimat lengkap: "彼は昨日も一昨日も来なかった。つまり、もう来ないつもりだろう。".',diagnosticFeedback:{"に〜かわって":'Salah: Pola "に〜かわって" bermakna "menggantikan ... / atas nama ...", yang tidak sesuai konteks kalimat ini.',のこと:'Salah: Pola "のこと" bermakna "tentang ... / hal mengenai ...", yang tidak sesuai konteks kalimat ini.',わけではない:'Salah: Pola "わけではない" bermakna "bukan berarti bahwa ... / tidak selalu ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜つまり secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["彼女は仕事もやめて、家族とも連絡を絶った。つまり、一人で生きていくつもりなのだ。","彼女は仕事もやめて、家族とも連絡を絶った。つまりでした、一人で生きていくつもりなのだ。","父にかわって、私が挨拶します。","本日は早退させていただきます。"],correctAnswer:"彼女は仕事もやめて、家族とも連絡を絶った。つまり、一人で生きていくつもりなのだ。",explanation:'Kalimat yang benar dan alami adalah "彼女は仕事もやめて、家族とも連絡を絶った。つまり、一人で生きていくつもりなのだ。" (Dia berhenti kerja dan memutus kontak dengan keluarga. Dengan kata lain, dia berniat hidup sendiri.).',diagnosticFeedback:{"彼女は仕事もやめて、家族とも連絡を絶った。つまりでした、一人で生きていくつもりなのだ。":"Jebakan Konjugasi: Pola 〜つまり membutuhkan aturan sambung (文1。つまり、文2。), bukan bentuk ini.","父にかわって、私が挨拶します。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜に〜かわって: menggantikan ... / atas nama ...), bukan kaidah 〜つまり.","本日は早退させていただきます。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜つまり secara tepat (maksudnya ... / dengan kata lain ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["父に かわって、 私が 挨拶します。","かわって、 父に 私が 挨拶します。","父に 私が かわって、 挨拶します。","挨拶します。 父に かわって、 私が"],correctAnswer:"父に かわって、 私が 挨拶します。",explanation:'Susunan yang benar: "父に かわって、 私が 挨拶します。" (Menggantikan ayah, saya yang akan menyampaikan sambutan.).',diagnosticFeedback:{"かわって、 父に 私が 挨拶します。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","父に 私が かわって、 挨拶します。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","挨拶します。 父に かわって、 私が":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["父に","かわって、","私が","挨拶します。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Audit berkala operasional pergudangan rantai pasok logistik lintas daerah.", saat Sakura menyampaikan arahan: 「なるほど。父にかわって、私が挨拶します。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜つまり dan 〜に〜かわって dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Audit berkala operasional pergudangan rantai pasok logistik lintas daerah.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜つまり!",modelAnswer:"はい、Sakuraさん！ 彼は昨日も一昨日も来なかった。つまり、もう来ないつもりだろう。。",modelAnswerId:"Ya, Sakura! Dia kemarin dan kemarin lusa tidak datang. Maksudnya, sepertinya dia sudah tidak berniat datang..",culturalEtiquette:"Sampaikan evaluasi deviasi secara objektif dengan memaparkan data pembanding yang valid.",skillUnlocked:["Menguasai formulasi pola 〜つまり","Mampu menerapkan prinsip koordinasi komunikasi kerja Kontras Paradoks, Ketidaksesuaian & Konsesi"]},pocket_summary:{keyFormula:"〜つまり (maksudnya ... / dengan kata lain ...)",coreWords:["友好【ゆうこう】 (persahabatan, hubungan baik (antarnegara, antarkota, atau kelompok besar))","友情【ゆうじょう】 (persahabatan, ikatan persahabatan, rasa setia kawan)","郵便【ゆうびん】 (pos, surat-menyurat, layanan pos)","ユーモア【ユーモア】 (humor, rasa humor, kelucuan)"],coreWarning:"Hindari memakai 〜kuse ni (padahal / bernada sinis) kepada kolega atau pelanggan kerja.",quickDialogue:"A: ブディさん、友好の 状況【じょうきょう】は どうで... → B: はい、Sakuraさん！ 彼は昨日も一昨日も来なか..."}},"les-n3-u16-02":{pedagogical_framework:{what:{summary:"Kontras Paradoks, Ketidaksesuaian & Konsesi (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜に対して, 〜に反して, 〜に加えて, 〜ばかりでなく dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜に対して dan 〜に反して secara mandiri.",targetPatterns:["〜に対して (terhadap ..., kepada ..., dibandingkan dengan ...)","〜に反して (berlawanan dengan ..., bertentangan dengan ...)","〜に加えて (ditambah dengan ..., selain ... juga ...)","〜ばかりでなく (bukan hanya ..., tidak hanya ...)"],coreVocabSample:["がん","かんこう","かんせい","かんりょう","きかん","きかん","きげん","きゅうりょう"]},sensei_context:{sceneIntro:"Audit berkala operasional pergudangan rantai pasok logistik lintas daerah. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜に対して dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kontras Paradoks, Ketidaksesuaian & Konsesi",etiquette:"Sampaikan evaluasi deviasi secara objektif dengan memaparkan data pembanding yang valid.",taboos:"Hindari memakai 〜kuse ni (padahal / bernada sinis) kepada kolega atau pelanggan kerja."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜に対して",moraNote:"Berikan jeda singkat setelah kata penghubung monono sebelum masuk ke klausa kontras.",soundTip:"Ucapkan 〜に対して dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜に対して",caseScenario:"Menggunakan 〜に対して tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜に対して.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜に対して sesuai kaidah.",explanation:"Kaidah koneksi 〜に対して: N + に対して / に対する + N."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Audit berkala operasional pergudangan rantai pasok logistik lintas daerah.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kontras Paradoks, Ketidaksesuaian & Konsesi (Produksi Aktif & Aplikasi Nyata)",setting:"Audit berkala operasional pergudangan rantai pasok logistik lintas daerah.",narrative:"Budi dan Sakura berkoordinasi mengenai alur operasional kerja menggunakan pola 〜に対して."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"ブディさん、癌の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、癌の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, gan no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai kanker, tumor ganas? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Sakuraさん！ 子供に対して、優しく接することが大切だ。。",furigana:"はい、Sakuraさん！ 子供に対して、優しく接することが大切だ。。",romaji:"Hai, Sakura-san! に対して de susumete imasu.",idText:"Ya, Sakura! Penting untuk bersikap baik terhadap anak-anak.."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"なるほど。予想に反して、試験は簡単だった。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。予想に反して、試験は簡単だった。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Berlawanan dengan perkiraan, ujiannya ternyata mudah.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01694",word:"癌",reading:"がん",romaji:"gan",meaning:"kanker, tumor ganas",pos:"noun",nuance:"Istilah medis dan percakapan untuk penyakit kanker (pertumbuhan sel ganas abnormal). Sering ditulis juga dengan katakana ガン atau hiragana がん dalam selebaran informasi kesehatan umum agar mudah dibaca masyarakat luas daripada bentuk kanjinya. Terkadang digunakan secara kiasan untuk masalah kronis paling parah yang merusak suatu institusi.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"癌【がん】を 確認【かくにん】します。",furigana:"癌を 確認します。",romaji:"gan o kakunin shimasu.",idText:"Memeriksa kanker, tumor ganas."}},{id:"vg-n3-01696",word:"慣行",reading:"かんこう",romaji:"kankou",meaning:"kebiasaan turun-temurun, praktik lazim, konvensi adat",pos:"noun",nuance:"Merujuk pada tindakan atau aturan tak tertulis yang sudah sejak lama dipraktikkan berulang kali dalam suatu komunitas, bidang industri, atau masyarakat hingga diakui sebagai standar norma bersama. Berbeda dengan 習慣 (shuukan) yang dapat merujuk pada rutinitas pribadi individu, 慣行 selalu melibatkan konvensi kelompok sosial atau institusi resmi.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"慣行【かんこう】を 確認【かくにん】します。",furigana:"慣行を 確認します。",romaji:"kankou o kakunin shimasu.",idText:"Memeriksa kebiasaan turun-temurun, praktik lazim, konvensi adat."}},{id:"vg-n3-01697",word:"歓声",reading:"かんせい",romaji:"kansei",meaning:"sorak-sorai gembira, pekik sukacita",pos:"noun",nuance:"Sorakan nyaring yang spontan dilontarkan oleh banyak orang secara serempak karena rasa sukacita, takjub, atau merayakan kemenangan (misalnya ketika tim mencetak gol atau artis pujaan tampil). Lazim dipadukan dengan 歓声が上がる (sorakan bergemuruh) atau 歓声を上げる (bersorak gembira). Berbeda dengan 叫び声 (sakebigoe) yang bisa berupa jeritan ketakutan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"歓声【かんせい】を 確認【かくにん】します。",furigana:"歓声を 確認します。",romaji:"kansei o kakunin shimasu.",idText:"Memeriksa sorak-sorai gembira, pekik sukacita."}},{id:"vg-n3-01698",word:"官僚",reading:"かんりょう",romaji:"kanryou",meaning:"birokrat, pejabat tinggi pemerintah",pos:"noun",nuance:"Merujuk kepada aparatur sipil negara tingkat tinggi di instansi kementerian pusat yang bertugas merancang kebijakan publik serta menyusun rancangan undang-undang (elite birokrasi pemerintahan). Berbeda dengan istilah 公務員 (koumuin) yang mencakup seluruh pegawai negeri termasuk petugas kantor pos, damkar, dan staf kelurahan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"官僚【かんりょう】を 確認【かくにん】します。",furigana:"官僚を 確認します。",romaji:"kanryou o kakunin shimasu.",idText:"Memeriksa birokrat, pejabat tinggi pemerintah."}},{id:"vg-n3-01699",word:"器官",reading:"きかん",romaji:"kikan",meaning:"organ tubuh, alat tubuh",pos:"noun",nuance:"Istilah biologis dan medis untuk bagian tubuh makhluk hidup yang menjalankan fungsi fisiologis tertentu, seperti mata, telinga, jantung, lambung, dan paru-paru (contoh: 呼吸器官 kokyuukikan = organ pernapasan; 感覚器官 kankakukikan = organ indra). Berbeda dengan kata 機関 (kikan = lembaga atau mesin) serta 期間 (kikan = jangka waktu).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"器官【きかん】を 確認【かくにん】します。",furigana:"器官を 確認します。",romaji:"kikan o kakunin shimasu.",idText:"Memeriksa organ tubuh, alat tubuh."}},{id:"vg-n3-01700",word:"季刊",reading:"きかん",romaji:"kikan",meaning:"terbitan tiga bulanan, terbitan per musim",pos:"noun",nuance:"Menyatakan pola penerbitan majalah, jurnal ilmiah, atau buletin berkala yang terbit 4 kali dalam setahun (setiap musim atau tiga bulan sekali). Sering dipakai sebagai pembentuk frasa 季刊誌 (kikanshi = majalah triwulanan). Berbeda dengan 月刊 (gekkan = terbit bulanan) dan 週刊 (shuukan = terbit mingguan).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"季刊【きかん】を 確認【かくにん】します。",furigana:"季刊を 確認します。",romaji:"kikan o kakunin shimasu.",idText:"Memeriksa terbitan tiga bulanan, terbitan per musim."}},{id:"vg-n3-01701",word:"起源",reading:"きげん",romaji:"kigen",meaning:"asal-usul, awal mula, titik awal permulaan",pos:"noun",nuance:"Merujuk pada waktu atau proses pertama kali sesuatu yang bersejarah, budaya, bahasa, atau fenomena alam muncul ke dunia. Berbeda dengan 原因 (gen'in) yang menyatakan penyebab langsung terjadinya suatu insiden atau akibat tertentu, 起源 berbicara mengenai silsilah sejarah dan awal muasal keberadaan suatu hal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"起源【きげん】を 確認【かくにん】します。",furigana:"起源を 確認します。",romaji:"kigen o kakunin shimasu.",idText:"Memeriksa asal-usul, awal mula, titik awal permulaan."}},{id:"vg-n3-01704",word:"丘陵",reading:"きゅうりょう",romaji:"kyuuryou",meaning:"perbukitan, bukit-bukit landai",pos:"noun",nuance:"Ragam geografis formal untuk bentang alam berupa deretan bukit yang relatif rendah dan permukaannya bergelombang landai tanpa lereng curam. Berbeda dengan kata 丘 (oka = bukit) yang merujuk pada satu gundukan bukit tunggal, 丘陵 merujuk pada bentangan wilayah perbukitan yang luas (contoh: 多摩丘陵 Tama kyuuryou).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"丘陵【きゅうりょう】を 確認【かくにん】します。",furigana:"丘陵を 確認します。",romaji:"kyuuryou o kakunin shimasu.",idText:"Memeriksa perbukitan, bukit-bukit landai."}}],explanations:[{id:"exp-1",grammarId:"gn3-00143",title:"Pola: 〜に対して",formula:"N + に対して / に対する + N",meaning:"terhadap ..., kepada ..., dibandingkan dengan ...",nuanceNotes:"〜に対して menyatakan arah suatu tindakan, sikap, atau perasaan yang ditujukan kepada objek tertentu. Selain itu, 〜に対して juga digunakan untuk membandingkan dua hal yang kontras. Bentuk 〜に対する digunakan sebelum kata benda.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に対して",idText:"terhadap ..., kepada ..., dibandingkan dengan ..."}],examples:[{jp:"子供に対して、優しく接することが大切だ。",romaji:"",idText:"Penting untuk bersikap baik terhadap anak-anak."},{jp:"彼の意見に対して、反論した。",romaji:"",idText:"Saya menentang pendapatnya."},{jp:"姉は社交的なに対して、妹は内向的だ。",romaji:"",idText:"Kakak perempuan sangat sosial, sedangkan adik perempuan lebih pendiam."}]},{id:"exp-2",grammarId:"gn3-00148",title:"Pola: 〜に反して",formula:"N + に反して / に反する + N",meaning:"berlawanan dengan ..., bertentangan dengan ...",nuanceNotes:"〜に反して menyatakan bahwa sesuatu terjadi secara berlawanan atau bertentangan dengan harapan, prediksi, aturan, atau keinginan tertentu. Pola ini menandai kontras yang tajam antara apa yang diharapkan dan apa yang sebenarnya terjadi.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に反して",idText:"berlawanan dengan ..., bertentangan dengan ..."}],examples:[{jp:"予想に反して、試験は簡単だった。",romaji:"",idText:"Berlawanan dengan perkiraan, ujiannya ternyata mudah."},{jp:"親の意見に反して、彼は会社を辞めた。",romaji:"",idText:"Bertentangan dengan pendapat orang tuanya, dia berhenti dari perusahaan."},{jp:"期待に反して、結果は良くなかった。",romaji:"",idText:"Berlawanan dengan harapan, hasilnya tidak bagus."}]},{id:"exp-3",grammarId:"gn3-00149",title:"Pola: 〜に加えて",formula:"N + に加えて",meaning:"ditambah dengan ..., selain ... juga ...",nuanceNotes:"〜に加えて menyatakan penambahan suatu hal di atas hal yang sudah ada. Digunakan untuk menyatakan bahwa selain X, Y juga ada atau terjadi. Pola ini umumnya digunakan dalam konteks formal dan menyiratkan bahwa hal yang ditambahkan memperkuat atau memperparah situasi yang sudah ada.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に加えて",idText:"ditambah dengan ..., selain ... juga ..."}],examples:[{jp:"語学力に加えて、コミュニケーション能力も必要だ。",romaji:"",idText:"Selain kemampuan bahasa, kemampuan komunikasi juga diperlukan."},{jp:"残業に加えて、休日出勤もある。",romaji:"",idText:"Selain lembur, ada juga kerja di hari libur."},{jp:"大雨に加えて、強風も吹いてきた。",romaji:"",idText:"Ditambah dengan hujan lebat, angin kencang pun mulai bertiup."}]},{id:"exp-4",grammarId:"gn3-00150",title:"Pola: 〜ばかりでなく",formula:"N / V-plain / い-Adj / な-Adj (な) + ばかりでなく",meaning:"bukan hanya ..., tidak hanya ...",nuanceNotes:'〜ばかりでなく menyatakan bahwa tidak hanya hal pertama (X) yang berlaku, tetapi juga hal lain (Y). Pola ini menekankan bahwa cakupan atau dampak sesuatu lebih luas dari yang diperkirakan. Sering diikuti oleh も pada klausa berikutnya untuk memperkuat makna "juga".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ばかりでなく",idText:"bukan hanya ..., tidak hanya ..."}],examples:[{jp:"彼女は歌が上手いばかりでなく、ダンスも得意だ。",romaji:"",idText:"Dia tidak hanya pandai menyanyi, tapi juga berbakat menari."},{jp:"この薬は痛みを和らげるばかりでなく、炎症も抑える。",romaji:"",idText:"Obat ini tidak hanya meredakan nyeri, tapi juga menekan peradangan."},{jp:"彼は日本語ばかりでなく、中国語も話せる。",romaji:"",idText:"Dia tidak hanya bisa berbicara bahasa Jepang, tapi juga bahasa Mandarin."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "癌"?',sentencePrompt:'Makna kata "癌" (がん) dalam situasi kerja ini adalah:',options:["kanker, tumor ganas","kebiasaan turun-temurun, praktik lazim, konvensi adat","sorak-sorai gembira, pekik sukacita","birokrat, pejabat tinggi pemerintah"],correctAnswer:"kanker, tumor ganas",explanation:'Makna yang tepat untuk "癌" adalah "kanker, tumor ganas".',diagnosticFeedback:{"kebiasaan turun-temurun, praktik lazim, konvensi adat":'Salah: Pilihan "kebiasaan turun-temurun, praktik lazim, konvensi adat" adalah makna dari kata "慣行" (かんこう), bukan arti kata "癌".',"sorak-sorai gembira, pekik sukacita":'Salah: Pilihan "sorak-sorai gembira, pekik sukacita" adalah makna dari kata "歓声" (かんせい), bukan arti kata "癌".',"birokrat, pejabat tinggi pemerintah":'Salah: Pilihan "birokrat, pejabat tinggi pemerintah" adalah makna dari kata "官僚" (かんりょう), bukan arti kata "癌".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"子供（　　）、優しく接することが大切だ。",options:["に対して","に反して","に加えて","わけではない"],correctAnswer:"に対して",explanation:'Pola 〜に対して bermakna "terhadap ..., kepada ..., dibandingkan dengan ...". Kalimat lengkap: "子供に対して、優しく接することが大切だ。".',diagnosticFeedback:{に反して:'Salah: Pola "に反して" bermakna "berlawanan dengan ..., bertentangan dengan ...", yang tidak sesuai konteks kalimat ini.',に加えて:'Salah: Pola "に加えて" bermakna "ditambah dengan ..., selain ... juga ...", yang tidak sesuai konteks kalimat ini.',わけではない:'Salah: Pola "わけではない" bermakna "bukan berarti bahwa ... / tidak selalu ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜に対して secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["彼の意見に対して、反論した。","彼の意見に対してでした、反論した。","予想に反して、試験は簡単だった。","本日は早退させていただきます。"],correctAnswer:"彼の意見に対して、反論した。",explanation:'Kalimat yang benar dan alami adalah "彼の意見に対して、反論した。" (Saya menentang pendapatnya.).',diagnosticFeedback:{"彼の意見に対してでした、反論した。":"Jebakan Konjugasi: Pola 〜に対して membutuhkan aturan sambung (N + に対して / に対する + N), bukan bentuk ini.","予想に反して、試験は簡単だった。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜に反して: berlawanan dengan ..., bertentangan dengan ...), bukan kaidah 〜に対して.","本日は早退させていただきます。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜に対して secara tepat (terhadap ..., kepada ..., dibandingkan dengan ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["予想に 反して、 試験は 簡単だった。","反して、 予想に 試験は 簡単だった。","予想に 試験は 反して、 簡単だった。","簡単だった。 予想に 反して、 試験は"],correctAnswer:"予想に 反して、 試験は 簡単だった。",explanation:'Susunan yang benar: "予想に 反して、 試験は 簡単だった。" (Berlawanan dengan perkiraan, ujiannya ternyata mudah.).',diagnosticFeedback:{"反して、 予想に 試験は 簡単だった。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","予想に 試験は 反して、 簡単だった。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","簡単だった。 予想に 反して、 試験は":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["予想に","反して、","試験は","簡単だった。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Audit berkala operasional pergudangan rantai pasok logistik lintas daerah.", saat Sakura menyampaikan arahan: 「なるほど。予想に反して、試験は簡単だった。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜に対して dan 〜に反して secara mandiri.",situation:"Situasi komunikasi profesional di Audit berkala operasional pergudangan rantai pasok logistik lintas daerah.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜に対して!",modelAnswer:"はい、Sakuraさん！ 子供に対して、優しく接することが大切だ。。",modelAnswerId:"Ya, Sakura! Penting untuk bersikap baik terhadap anak-anak..",culturalEtiquette:"Sampaikan evaluasi deviasi secara objektif dengan memaparkan data pembanding yang valid.",skillUnlocked:["Menguasai formulasi pola 〜に対して","Mampu menerapkan prinsip koordinasi komunikasi kerja Kontras Paradoks, Ketidaksesuaian & Konsesi"]},pocket_summary:{keyFormula:"〜に対して (terhadap ..., kepada ..., dibandingkan dengan ...)",coreWords:["癌【がん】 (kanker, tumor ganas)","慣行【かんこう】 (kebiasaan turun-temurun, praktik lazim, konvensi adat)","歓声【かんせい】 (sorak-sorai gembira, pekik sukacita)","官僚【かんりょう】 (birokrat, pejabat tinggi pemerintah)"],coreWarning:"Hindari memakai 〜kuse ni (padahal / bernada sinis) kepada kolega atau pelanggan kerja.",quickDialogue:"A: ブディさん、癌の 状況【じょうきょう】は どうです... → B: はい、Sakuraさん！ 子供に対して、優しく接す..."}}},e={"les-n3-u17-01":{pedagogical_framework:{what:{summary:"Sudut Pandang, Kedudukan Resmi & Kompensasi (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜わけではない, 〜ものではない, 〜もの / 〜もん, 〜ものだから / 〜もので, 〜ことにしている dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜わけではない dan 〜ものではない dalam percakapan kerja wajar.",targetPatterns:["〜わけではない (bukan berarti bahwa ... / tidak selalu ...)","〜ものではない (tidak pantas untuk ... / janganlah ... / tidak baik ...)","〜もの / 〜もん (karena ... / habisnya sih ... (alasan santai / pembenaran diri))","〜ものだから / 〜もので (berhubung ... / karena alasan tak terelakkan ...)","〜ことにしている (membiasakan diri untuk ... / punya kebiasaan ...)"],coreVocabSample:["タイプライター","だいめい","ダイヤ","たいよう","たいりく","タオル","だが","たがい"]},sensei_context:{sceneIntro:"Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜わけではない dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Sudut Pandang, Kedudukan Resmi & Kompensasi",etiquette:"Awali pernyataan resmi dengan kedudukan Anda (contoh: Daihyou to shite) agar konteks wewenang dipahami.",taboos:"Jangan tertukar antara 〜to shite (kapasitas peran) dengan 〜ni totte (sudut pandang evaluatif)."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜わけではない",moraNote:"Artikulasikan to shi-te dengan tegas berwibawa tanpa ragu-ragu.",soundTip:"Ucapkan 〜わけではない dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜わけではない",caseScenario:"Menggunakan 〜わけではない tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜わけではない.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜わけではない sesuai kaidah.",explanation:"Kaidah koneksi 〜わけではない: V-plain / Adj-い / Adj-な + な / N + という + わけではない."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Sudut Pandang, Kedudukan Resmi & Kompensasi (Fondasi & Pemahaman Pola)",setting:"Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat.",narrative:"Budi dan Sato berkoordinasi mengenai alur operasional kerja menggunakan pola 〜わけではない."}},dialogue:[{id:"d1",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"ブディさん、タイプライターの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、タイプライターの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, taipuraitaa no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai mesin tik? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Satoさん！ 料理が嫌いなわけではないが、毎日作る時間がない。。",furigana:"はい、Satoさん！ 料理が嫌いなわけではないが、毎日作る時間がない。。",romaji:"Hai, Sato-san! わけではない de susumete imasu.",idText:"Ya, Sato! Bukan berarti saya benci memasak, tapi saya tidak punya waktu untuk memasak setiap hari.."},{id:"d3",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"なるほど。目上の人にそんな口の利き方をするものではない。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。目上の人にそんな口の利き方をするものではない。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Tidak pantas berbicara seperti itu kepada atasan atau orang yang lebih tua.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01807",word:"タイプライター",reading:"タイプライター",romaji:"taipuraitaa",meaning:"mesin tik",pos:"noun",nuance:"Mesin ketik mekanik manual atau elektrik yang digunakan untuk mencetak huruf pada kertas sebelum era komputer pribadi berkembang. Kini umumnya dipandang sebagai benda klasik, barang koleksi antik, atau referensi sejarah kantor.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"タイプライターを 確認【かくにん】します。",furigana:"タイプライターを 確認します。",romaji:"taipuraitaa o kakunin shimasu.",idText:"Memeriksa mesin tik."}},{id:"vg-n3-01809",word:"題名",reading:"だいめい",romaji:"daimei",meaning:"judul (buku, lagu, film, karya)",pos:"noun",nuance:"Nama atau judul resmi yang disematkan pada suatu karya seni, buku, novel, film, atau lagu. Berbeda dengan 表題 (hyoudai) yang lebih sering digunakan untuk tajuk dokumen atau berkas resmi, 題名 sangat akrab dipakai dalam keseharian untuk karya sastra, seni, dan media hiburan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"題名【だいめい】を 確認【かくにん】します。",furigana:"題名を 確認します。",romaji:"daimei o kakunin shimasu.",idText:"Memeriksa judul (buku, lagu, film, karya)."}},{id:"vg-n3-01810",word:"ダイヤ",reading:"ダイヤ",romaji:"daiya",meaning:"jadwal perjalanan (kereta api); intan, berlian",pos:"noun",nuance:"Memiliki dua makna: 1) Singkatan dari ダイヤグラム (diagram jadwal operasional kereta api/bus di Jepang); 2) Singkatan dari ダイヤモンド (berlian/intan). Dalam kehidupan sehari-hari di Jepang, ダイヤ paling umum terdengar dalam pengumuman stasiun terkait perubahan atau keterlambatan jadwal kereta (seperti ダイヤの乱れ 'gangguan jadwal perjalanan kereta').",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ダイヤを 確認【かくにん】します。",furigana:"ダイヤを 確認します。",romaji:"daiya o kakunin shimasu.",idText:"Memeriksa jadwal perjalanan (kereta api); intan, berlian."}},{id:"vg-n3-01811",word:"太陽",reading:"たいよう",romaji:"taiyou",meaning:"matahari",pos:"noun",nuance:"Bintang pusat tata surya yang memancarkan cahaya dan panas. Digunakan sebagai istilah objektif, ilmiah, dan umum (seperti 太陽光 'cahaya matahari', 太陽系 'tata surya'). Berbeda dengan 日 (hi) yang lebih puitis, kasual, atau merujuk pada sinar panas matahari terik (misal 日に当たる 'berjemur/terkena sinar mentari').",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"太陽【たいよう】を 確認【かくにん】します。",furigana:"太陽を 確認します。",romaji:"taiyou o kakunin shimasu.",idText:"Memeriksa matahari."}},{id:"vg-n3-01814",word:"大陸",reading:"たいりく",romaji:"tairiku",meaning:"benua, daratan luas",pos:"noun",nuance:"Daratan sangat luas yang memisahkan samudera-samudera di bumi (seperti アジア大陸 'Benua Asia', アフリカ大陸 'Benua Afrika'). Berbeda dengan 島 (shima) yang merupakan pulau yang dikelilingi laut, 大陸 merujuk pada daratan induk berskala global.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"大陸【たいりく】を 確認【かくにん】します。",furigana:"大陸を 確認します。",romaji:"tairiku o kakunin shimasu.",idText:"Memeriksa benua, daratan luas."}},{id:"vg-n3-01815",word:"タオル",reading:"タオル",romaji:"taoru",meaning:"handuk",pos:"noun",nuance:"Kain penyerap air yang digunakan untuk mengeringkan badan, wajah, atau tangan setelah mandi atau saat berkeringat (misal バスタオル 'handuk mandi', フェイスタオル 'handuk wajah'). Berbeda dengan 手ぬぐい (tenugui) yang merupakan kain katun tipis tradisional khas Jepang tanpa bulu serat handuk.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"タオルを 確認【かくにん】します。",furigana:"タオルを 確認します。",romaji:"taoru o kakunin shimasu.",idText:"Memeriksa handuk."}},{id:"vg-n3-01816",word:"だが",reading:"だが",romaji:"daga",meaning:"tetapi, namun, akan tetapi",pos:"conjunction",nuance:"Konjungsi pertentangan (adversatif) bernada tegas dan lugas, sering digunakan dalam tulisan tertulis, esai, berita, atau tuturan monolog maskulin/netral di awal kalimat. Berbeda dengan でも (demo) yang lebih kasual dan lisan, atau しかし (shikashi) yang sangat umum dan standar untuk berbagai ragam situasi, だが terkesan lebih singkat, berbobot, dan berjarak intelektual.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"だがを 確認【かくにん】します。",furigana:"だがを 確認します。",romaji:"daga o kakunin shimasu.",idText:"Memeriksa tetapi, namun, akan tetapi."}},{id:"vg-n3-01817",word:"互い",reading:"たがい",romaji:"tagai",meaning:"satu sama lain, saling, timbal balik",pos:"noun",nuance:"Menyatakan relasi timbal balik antara dua pihak atau lebih. Paling sering digunakan dalam bentuk お互いに (o-tagai ni - 'saling / bersama-sama') atau お互いの (o-tagai no - 'milik satu sama lain'). Membawa nuansa kebersamaan dan kerja sama seimbang dalam suatu relasi persahabatan, asmara, maupun kerja tim.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"互い【たがい】を 確認【かくにん】します。",furigana:"互いを 確認します。",romaji:"tagai o kakunin shimasu.",idText:"Memeriksa satu sama lain, saling, timbal balik."}}],explanations:[{id:"exp-1",grammarId:"gn3-00100",title:"Pola: 〜わけではない",formula:"V-plain / Adj-い / Adj-な + な / N + という + わけではない",meaning:"bukan berarti bahwa ... / tidak selalu ...",nuanceNotes:'〜わけではない menyatakan penolakan parsial atau halus terhadap asumsi pendengar. "Bukan berarti bahwa...", "tidak selalu...". Sering dipakai bersama kata seperti いつも, 全部, atau 必ずしも.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜わけではない",idText:"bukan berarti bahwa ... / tidak selalu ..."}],examples:[{jp:"料理が嫌いなわけではないが、毎日作る時間がない。",romaji:"",idText:"Bukan berarti saya benci memasak, tapi saya tidak punya waktu untuk memasak setiap hari."},{jp:"値段が高ければおいしいというわけではない。",romaji:"",idText:"Bukan berarti barang yang mahal itu pasti enak."},{jp:"全然分からないわけではありませんが、もう少しゆっくり話していただけますか。",romaji:"",idText:"Bukan berarti saya sama sekali tidak mengerti, tapi bisakah bicara sedikit lebih pelan?"}]},{id:"exp-2",grammarId:"gn3-00105",title:"Pola: 〜ものではない",formula:"Vる + ものではない",meaning:"tidak pantas untuk ... / janganlah ... / tidak baik ...",nuanceNotes:'〜ものではない digunakan untuk memberikan nasihat atau teguran moral berdasarkan norma umum bahwa sesuatu tidak pantas dilakukan. "Tidak seharusnya...", "janganlah...".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ものではない",idText:"tidak pantas untuk ... / janganlah ... / tidak baik ..."}],examples:[{jp:"目上の人にそんな口の利き方をするものではない。",romaji:"",idText:"Tidak pantas berbicara seperti itu kepada atasan atau orang yang lebih tua."},{jp:"人の悪口を言うものではありません。",romaji:"",idText:"Janganlah membicarakan keburukan orang lain."}]},{id:"exp-3",grammarId:"gn3-00106",title:"Pola: 〜もの / 〜もん",formula:"V-plain / Adj-い / Adj-な / N + だ + もの / もん",meaning:"karena ... / habisnya sih ... (alasan santai / pembenaran diri)",nuanceNotes:'〜もの / 〜もん dipakai di akhir kalimat dalam percakapan santai untuk memberikan alasan atau pembelaan diri. Sering terdengar pada tuturan anak-anak atau wanita muda. "Habisnya sih...", "soalnya...".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜もの / 〜もん",idText:"karena ... / habisnya sih ... (alasan santai / pembenaran diri)"}],examples:[{jp:"「どうして食べないの？」「だって、おいしくないんだもん。」",romaji:"",idText:"「Kenapa tidak dimakan?」「Habisnya tidak enak sih.」"},{jp:"遅刻したのは電車の事故があったんだもの。",romaji:"",idText:"Saya terlambat karena ada kecelakaan kereta kok."}]},{id:"exp-4",grammarId:"gn3-00107",title:"Pola: 〜ものだから / 〜もので",formula:"V-plain / Adj-い / Adj-な + な / N + な + ものだから / もので",meaning:"berhubung ... / karena alasan tak terelakkan ...",nuanceNotes:"〜ものだから / 〜もので memberikan alasan pembenaran yang bernuansa objektif atau di luar kendali pembicara saat meminta maaf atau menjelaskan kesalahan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ものだから / 〜もので",idText:"berhubung ... / karena alasan tak terelakkan ..."}],examples:[{jp:"道が混んでいたものだから、遅れてしまいました。",romaji:"",idText:"Berhubung jalannya macet, saya jadi terlambat."},{jp:"急な用事ができたもので、失礼いたします。",romaji:"",idText:"Karena ada urusan mendadak, saya mohon pamit."}]},{id:"exp-5",grammarId:"gn3-00108",title:"Pola: 〜ことにしている",formula:"Vる / Vない + ことにしている",meaning:"membiasakan diri untuk ... / punya kebiasaan ...",nuanceNotes:'〜ことにしている menyatakan keputusan pribadi yang dijalankan secara rutin menjadi kebiasaan hidup. "Saya membiasakan diri untuk...".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことにしている",idText:"membiasakan diri untuk ... / punya kebiasaan ..."}],examples:[{jp:"健康のために、毎朝ジョギングをすることにしています。",romaji:"",idText:"Demi kesehatan, saya membiasakan diri joging setiap pagi."},{jp:"夜遅くには甘いものを食べないことにしている。",romaji:"",idText:"Saya membiasakan diri tidak makan makanan manis di larut malam."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "タイプライター"?',sentencePrompt:'Makna kata "タイプライター" (タイプライター) dalam situasi kerja ini adalah:',options:["mesin tik","judul (buku, lagu, film, karya)","jadwal perjalanan (kereta api); intan, berlian","matahari"],correctAnswer:"mesin tik",explanation:'Makna yang tepat untuk "タイプライター" adalah "mesin tik".',diagnosticFeedback:{"judul (buku, lagu, film, karya)":'Salah: Pilihan "judul (buku, lagu, film, karya)" adalah makna dari kata "題名" (だいめい), bukan arti kata "タイプライター".',"jadwal perjalanan (kereta api); intan, berlian":'Salah: Pilihan "jadwal perjalanan (kereta api); intan, berlian" adalah makna dari kata "ダイヤ" (ダイヤ), bukan arti kata "タイプライター".',matahari:'Salah: Pilihan "matahari" adalah makna dari kata "太陽" (たいよう), bukan arti kata "タイプライター".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"料理が嫌いな（　　）が、毎日作る時間がない。",options:["わけではない","ものではない","もの / 〜もん","一方で"],correctAnswer:"わけではない",explanation:'Pola 〜わけではない bermakna "bukan berarti bahwa ... / tidak selalu ...". Kalimat lengkap: "料理が嫌いなわけではないが、毎日作る時間がない。".',diagnosticFeedback:{ものではない:'Salah: Pola "ものではない" bermakna "tidak pantas untuk ... / janganlah ... / tidak baik ...", yang tidak sesuai konteks kalimat ini.',"もの / 〜もん":'Salah: Pola "もの / 〜もん" bermakna "karena ... / habisnya sih ... (alasan santai / pembenaran diri)", yang tidak sesuai konteks kalimat ini.',一方で:'Salah: Pola "一方で" bermakna "di satu sisi ... di sisi lain ... / sementara itu", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜わけではない secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["値段が高ければおいしいというわけではない。","値段が高ければおいしいというわけではないでした。","目上の人にそんな口の利き方をするものではない。","若いうちに、いろいろな経験をしてください。"],correctAnswer:"値段が高ければおいしいというわけではない。",explanation:'Kalimat yang benar dan alami adalah "値段が高ければおいしいというわけではない。" (Bukan berarti barang yang mahal itu pasti enak.).',diagnosticFeedback:{"値段が高ければおいしいというわけではないでした。":"Jebakan Konjugasi: Pola 〜わけではない membutuhkan aturan sambung (V-plain / Adj-い / Adj-な + な / N + という + わけではない), bukan bentuk ini.","目上の人にそんな口の利き方をするものではない。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ものではない: tidak pantas untuk ... / janganlah ... / tidak baik ...), bukan kaidah 〜わけではない.","若いうちに、いろいろな経験をしてください。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜わけではない secara tepat (bukan berarti bahwa ... / tidak selalu ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["目上の人に そんな口の 利き方をする ものではない。","そんな口の 目上の人に 利き方をする ものではない。","目上の人に 利き方をする そんな口の ものではない。","ものではない。 目上の人に そんな口の 利き方をする"],correctAnswer:"目上の人に そんな口の 利き方をする ものではない。",explanation:'Susunan yang benar: "目上の人に そんな口の 利き方をする ものではない。" (Tidak pantas berbicara seperti itu kepada atasan atau orang yang lebih tua.).',diagnosticFeedback:{"そんな口の 目上の人に 利き方をする ものではない。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","目上の人に 利き方をする そんな口の ものではない。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","ものではない。 目上の人に そんな口の 利き方をする":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["目上の人に","そんな口の","利き方をする","ものではない。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat.", saat Sato menyampaikan arahan: 「なるほど。目上の人にそんな口の利き方をするものではない。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜わけではない dan 〜ものではない dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜わけではない!",modelAnswer:"はい、Satoさん！ 料理が嫌いなわけではないが、毎日作る時間がない。。",modelAnswerId:"Ya, Sato! Bukan berarti saya benci memasak, tapi saya tidak punya waktu untuk memasak setiap hari..",culturalEtiquette:"Awali pernyataan resmi dengan kedudukan Anda (contoh: Daihyou to shite) agar konteks wewenang dipahami.",skillUnlocked:["Menguasai formulasi pola 〜わけではない","Mampu menerapkan prinsip koordinasi komunikasi kerja Sudut Pandang, Kedudukan Resmi & Kompensasi"]},pocket_summary:{keyFormula:"〜わけではない (bukan berarti bahwa ... / tidak selalu ...)",coreWords:["タイプライター【タイプライター】 (mesin tik)","題名【だいめい】 (judul (buku, lagu, film, karya))","ダイヤ【ダイヤ】 (jadwal perjalanan (kereta api); intan, berlian)","太陽【たいよう】 (matahari)"],coreWarning:"Jangan tertukar antara 〜to shite (kapasitas peran) dengan 〜ni totte (sudut pandang evaluatif).",quickDialogue:"A: ブディさん、タイプライターの 状況【じょうきょう】... → B: はい、Satoさん！ 料理が嫌いなわけではないが、..."}},"les-n3-u17-02":{pedagogical_framework:{what:{summary:"Sudut Pandang, Kedudukan Resmi & Kompensasi (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜こと（instruksi）, 〜ように言う / 〜ように頼む, 〜そうにない / 〜そうもない, 〜一方だ dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜こと（instruksi） dan 〜ように言う / 〜ように頼む secara mandiri.",targetPatterns:["〜こと（instruksi） (wajib ... / harus ... (instruksi / aturan tertulis))","〜ように言う / 〜ように頼む (menyampaikan pesan agar ... / meminta agar ...)","〜そうにない / 〜そうもない (tampaknya mustahil ... / kecil kemungkinan untuk ...)","〜一方だ (semakin bertambah ... / terus-menerus ke satu arah)"],coreVocabSample:["で","であい","であい","ていき","ていでん","ていりゅうじょ","デート","てき"]},sensei_context:{sceneIntro:"Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜こと（instruksi） dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Sudut Pandang, Kedudukan Resmi & Kompensasi",etiquette:"Awali pernyataan resmi dengan kedudukan Anda (contoh: Daihyou to shite) agar konteks wewenang dipahami.",taboos:"Jangan tertukar antara 〜to shite (kapasitas peran) dengan 〜ni totte (sudut pandang evaluatif)."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜こと（instruksi）",moraNote:"Artikulasikan to shi-te dengan tegas berwibawa tanpa ragu-ragu.",soundTip:"Ucapkan 〜こと（instruksi） dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜こと（instruksi）",caseScenario:"Menggunakan 〜こと（instruksi） tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜こと（instruksi）.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜こと（instruksi） sesuai kaidah.",explanation:"Kaidah koneksi 〜こと（instruksi）: Vる / Vない + こと."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Sudut Pandang, Kedudukan Resmi & Kompensasi (Produksi Aktif & Aplikasi Nyata)",setting:"Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat.",narrative:"Budi dan Sato berkoordinasi mengenai alur operasional kerja menggunakan pola 〜こと（instruksi）."}},dialogue:[{id:"d1",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"ブディさん、出の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、出の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, de no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai asal kelulusan/daerah, keluaran, kelancaran aliran air? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Satoさん！ レポートは来週の金曜日までに提出すること。。",furigana:"はい、Satoさん！ レポートは来週の金曜日までに提出すること。。",romaji:"Hai, Sato-san! こと de susumete imasu.",idText:"Ya, Sato! Laporan wajib dikumpulkan paling lambat hari Jumat minggu depan.."},{id:"d3",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"なるほど。先生から、明日早く来るように言われました。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。先生から、明日早く来るように言われました。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Saya diberitahu oleh guru agar datang lebih awal besok.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01929",word:"出",reading:"で",romaji:"de",meaning:"asal kelulusan/daerah, keluaran, kelancaran aliran air",pos:"noun",nuance:"Nomina dari kata kerja 出る (deru). Memiliki beberapa arti lazim: 1) Asal almamater kampus atau latar belakang kedaerahan (東京大学の出 = lulusan Universitas Tokyo, 田舎の出 = berlatar anak daerah); 2) Kelancaran debit pancaran atau aliran cairan (水の出が悪い = pancaran airnya kurang lancar/mampet); 3) Kemunculan benda langit (日の出 = matahari terbit).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"出【で】を 確認【かくにん】します。",furigana:"出を 確認します。",romaji:"de o kakunin shimasu.",idText:"Memeriksa asal kelulusan/daerah, keluaran, kelancaran aliran air."}},{id:"vg-n3-01930",word:"出会い",reading:"であい",romaji:"deai",meaning:"pertemuan pertama kali, perjumpaan berharga",pos:"noun",nuance:"Bentuk nomina dari kata kerja 出会う. Menekankan momen perjumpaan awal yang berkesan dan membuka relasi baru dengan orang lain, buku, atau pengalaman hidup (misal: 運命的な出会い = perjumpaan takdir, 人生の出会い = perjumpaan penting dalam hidup). Kanji 出会い paling umum dipakai untuk hubungan antarsesama manusia.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"出会い【であい】を 確認【かくにん】します。",furigana:"出会いを 確認します。",romaji:"deai o kakunin shimasu.",idText:"Memeriksa pertemuan pertama kali, perjumpaan berharga."}},{id:"vg-n3-01931",word:"出合い",reading:"であい",romaji:"deai",meaning:"pertemuan tak terduga, perjumpaan insidental, pertemuan arus",pos:"noun",nuance:"Varian penulisan dari であい. Sementara 出会い berfokus pada relasi antarsesama manusia atau takdir, penulisan 出合い lebih sering muncul dalam konteks kejadian insidental yang serba mendadak (misal: 出合い頭の事故 = tabrakan di persimpangan jalan saat sama-sama melaju mendadak) atau pertemuan dua aliran air sungai/lembah.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"出合い【であい】を 確認【かくにん】します。",furigana:"出合いを 確認します。",romaji:"deai o kakunin shimasu.",idText:"Memeriksa pertemuan tak terduga, perjumpaan insidental, pertemuan arus."}},{id:"vg-n3-01933",word:"定期",reading:"ていき",romaji:"teiki",meaning:"berkala, waktu teratur, tiket langganan komuter (kereta/bus)",pos:"noun",nuance:"Memiliki dua penggunaan pokok: 1) Sesuatu yang berlangsung secara berulang dalam kurun waktu teratur (misal: 定期試験 = ujian berkala/semester, 定期健康診断 = pemeriksaan medis berkala); 2) Singkatan sehari-hari yang sangat populer untuk 定期券 (kartu langganan komuter kereta/bus bulanan).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"定期【ていき】を 確認【かくにん】します。",furigana:"定期を 確認します。",romaji:"teiki o kakunin shimasu.",idText:"Memeriksa berkala, waktu teratur, tiket langganan komuter (kereta/bus)."}},{id:"vg-n3-01936",word:"停電",reading:"ていでん",romaji:"teiden",meaning:"pemadaman listrik, mati lampu",pos:"noun",nuance:"Merujuk pada kondisi terputusnya aliran listrik, baik karena bencana alam, perawatan jaringan, maupun kerusakan gardu. Berbeda dengan 断水 (dansui) yang merujuk pada pemadaman pasokan air bersih, 停電 khusus untuk energi listrik. Sering digabungkan dengan kata kerja 起こる (terjadi), する (mengalami padam listrik), atau 復旧する (pulih kembali).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"停電【ていでん】を 確認【かくにん】します。",furigana:"停電を 確認します。",romaji:"teiden o kakunin shimasu.",idText:"Memeriksa pemadaman listrik, mati lampu."}},{id:"vg-n3-01937",word:"停留所",reading:"ていりゅうじょ",romaji:"teiryuujo",meaning:"tempat pemberhentian bus, halte",pos:"noun",nuance:"Istilah formal atau tertulis untuk tempat naik dan turunnya penumpang bus atau trem di tepi jalan. Berbeda dengan sebutan sehari-hari バス停 (basutei) yang lebih santai dan lumrah diucapkan langsung dalam obrolan lisan, 停留所 lebih sering tercantum pada dokumen trayek resmi, undang-undang lalu lintas, serta papan penunjuk arah formal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"停留所【ていりゅうじょ】を 確認【かくにん】します。",furigana:"停留所を 確認します。",romaji:"teiryuujo o kakunin shimasu.",idText:"Memeriksa tempat pemberhentian bus, halte."}},{id:"vg-n3-01938",word:"デート",reading:"デート",romaji:"deeto",meaning:"kencan, jalan berdua bersama pasangan",pos:"noun",nuance:"Khusus merujuk pada janji temu romantis atau jalan-jalan berdua antara pasangan kekasih atau orang yang saling menyukai. Berbeda dengan kata serapan bahasa Inggris 'date' yang juga mencakup tanggal kalender (dalam bahasa Jepang memakai 日付 hizuke), kata デート dalam bahasa Jepang murni hanya digunakan untuk kencan asmara.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"デートを 確認【かくにん】します。",furigana:"デートを 確認します。",romaji:"deeto o kakunin shimasu.",idText:"Memeriksa kencan, jalan berdua bersama pasangan."}},{id:"vg-n3-01939",word:"敵",reading:"てき",romaji:"teki",meaning:"musuh, lawan, penantang",pos:"noun",nuance:"Menyatakan pihak penantang, lawan berseteru, atau pihak yang dihadapi untuk dikalahkan. Berbeda dengan ライバル (raibaru) atau 相手 (aite) yang bernuansa netral atau suportif demi kemajuan bersama, 敵 sering mengandung nuansa pertentangan keras atau kebencian, meskipun dalam konteks olahraga dan permainan sering disandingkan dengan 味方 (kawan/sekutu).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"敵【てき】を 確認【かくにん】します。",furigana:"敵を 確認します。",romaji:"teki o kakunin shimasu.",idText:"Memeriksa musuh, lawan, penantang."}}],explanations:[{id:"exp-1",grammarId:"gn3-00109",title:"Pola: 〜こと（instruksi）",formula:"Vる / Vない + こと",meaning:"wajib ... / harus ... (instruksi / aturan tertulis)",nuanceNotes:"〜こと digunakan dalam pengumuman tertulis, papan peraturan, atau instruksi ujian untuk memerintahkan atau melarang tindakan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜こと（instruksi）",idText:"wajib ... / harus ... (instruksi / aturan tertulis)"}],examples:[{jp:"レポートは来週の金曜日までに提出すること。",romaji:"",idText:"Laporan wajib dikumpulkan paling lambat hari Jumat minggu depan."},{jp:"試験中は携帯電話の電源を切ること。",romaji:"",idText:"Selama ujian wajib mematikan daya ponsel."}]},{id:"exp-2",grammarId:"gn3-00110",title:"Pola: 〜ように言う / 〜ように頼む",formula:"Vる / Vない + ように言う / 頼む / 伝える",meaning:"menyampaikan pesan agar ... / meminta agar ...",nuanceNotes:"〜ように言う / 頼む digunakan untuk kalimat tidak langsung (reported speech) saat meneruskan perintah atau permohonan dari pihak lain.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ように言う / 〜ように頼む",idText:"menyampaikan pesan agar ... / meminta agar ..."}],examples:[{jp:"先生から、明日早く来るように言われました。",romaji:"",idText:"Saya diberitahu oleh guru agar datang lebih awal besok."},{jp:"田中さんに書類を持ってくるように頼んでください。",romaji:"",idText:"Tolong mintalah kepada Tanaka-san agar membawa dokumennya."}]},{id:"exp-3",grammarId:"gn3-00111",title:"Pola: 〜そうにない / 〜そうもない",formula:"V-stem + そうにない / そうもない",meaning:"tampaknya mustahil ... / kecil kemungkinan untuk ...",nuanceNotes:"〜そうにない menyatakan perkiraan negatif pembicara bahwa sesuatu tampaknya tidak mungkin terjadi berdasarkan pengamatan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜そうにない / 〜そうもない",idText:"tampaknya mustahil ... / kecil kemungkinan untuk ..."}],examples:[{jp:"この雨はまだやみそうにない。",romaji:"",idText:"Hujan ini tampaknya belum akan reda."},{jp:"締め切りまでに仕事が終わりそうもありません。",romaji:"",idText:"Pekerjaan ini tampaknya mustahil selesai sebelum tenggat waktu."}]},{id:"exp-4",grammarId:"gn3-00112",title:"Pola: 〜一方だ",formula:"Vる + 一方だ",meaning:"semakin bertambah ... / terus-menerus ke satu arah",nuanceNotes:"〜一方だ menyatakan bahwa suatu tren atau perubahan terus berlanjut ke satu arah (biasanya memburuk atau meningkat tajam).",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜一方だ",idText:"semakin bertambah ... / terus-menerus ke satu arah"}],examples:[{jp:"物価が上がる一方だ。",romaji:"",idText:"Harga barang terus-menerus naik."},{jp:"祖父の病気は悪くなる一方です。",romaji:"",idText:"Penyakit kakek saya terus memburuk."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "出"?',sentencePrompt:'Makna kata "出" (で) dalam situasi kerja ini adalah:',options:["asal kelulusan/daerah, keluaran, kelancaran aliran air","pertemuan pertama kali, perjumpaan berharga","pertemuan tak terduga, perjumpaan insidental, pertemuan arus","berkala, waktu teratur, tiket langganan komuter (kereta/bus)"],correctAnswer:"asal kelulusan/daerah, keluaran, kelancaran aliran air",explanation:'Makna yang tepat untuk "出" adalah "asal kelulusan/daerah, keluaran, kelancaran aliran air".',diagnosticFeedback:{"pertemuan pertama kali, perjumpaan berharga":'Salah: Pilihan "pertemuan pertama kali, perjumpaan berharga" adalah makna dari kata "出会い" (であい), bukan arti kata "出".',"pertemuan tak terduga, perjumpaan insidental, pertemuan arus":'Salah: Pilihan "pertemuan tak terduga, perjumpaan insidental, pertemuan arus" adalah makna dari kata "出合い" (であい), bukan arti kata "出".',"berkala, waktu teratur, tiket langganan komuter (kereta/bus)":'Salah: Pilihan "berkala, waktu teratur, tiket langganan komuter (kereta/bus)" adalah makna dari kata "定期" (ていき), bukan arti kata "出".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"レポートは来週の金曜日までに提出する（　　）。",options:["こと","ように言う / 〜ように頼む","そうにない / 〜そうもない","一方で"],correctAnswer:"こと",explanation:'Pola 〜こと（instruksi） bermakna "wajib ... / harus ... (instruksi / aturan tertulis)". Kalimat lengkap: "レポートは来週の金曜日までに提出すること。".',diagnosticFeedback:{"ように言う / 〜ように頼む":'Salah: Pola "ように言う / 〜ように頼む" bermakna "menyampaikan pesan agar ... / meminta agar ...", yang tidak sesuai konteks kalimat ini.',"そうにない / 〜そうもない":'Salah: Pola "そうにない / 〜そうもない" bermakna "tampaknya mustahil ... / kecil kemungkinan untuk ...", yang tidak sesuai konteks kalimat ini.',一方で:'Salah: Pola "一方で" bermakna "di satu sisi ... di sisi lain ... / sementara itu", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜こと（instruksi） secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["試験中は携帯電話の電源を切ること。","試験中は携帯電話の電源を切ることでした。","先生から、明日早く来るように言われました。","若いうちに、いろいろな経験をしてください。"],correctAnswer:"試験中は携帯電話の電源を切ること。",explanation:'Kalimat yang benar dan alami adalah "試験中は携帯電話の電源を切ること。" (Selama ujian wajib mematikan daya ponsel.).',diagnosticFeedback:{"試験中は携帯電話の電源を切ることでした。":"Jebakan Konjugasi: Pola 〜こと（instruksi） membutuhkan aturan sambung (Vる / Vない + こと), bukan bentuk ini.","先生から、明日早く来るように言われました。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ように言う / 〜ように頼む: menyampaikan pesan agar ... / meminta agar ...), bukan kaidah 〜こと（instruksi）.","若いうちに、いろいろな経験をしてください。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜こと（instruksi） secara tepat (wajib ... / harus ... (instruksi / aturan tertulis))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["先生から、 明日早く 来るように 言われました。","明日早く 先生から、 来るように 言われました。","先生から、 来るように 明日早く 言われました。","言われました。 先生から、 明日早く 来るように"],correctAnswer:"先生から、 明日早く 来るように 言われました。",explanation:'Susunan yang benar: "先生から、 明日早く 来るように 言われました。" (Saya diberitahu oleh guru agar datang lebih awal besok.).',diagnosticFeedback:{"明日早く 先生から、 来るように 言われました。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","先生から、 来るように 明日早く 言われました。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","言われました。 先生から、 明日早く 来るように":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["先生から、","明日早く","来るように","言われました。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat.", saat Sato menyampaikan arahan: 「なるほど。先生から、明日早く来るように言われました。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜こと（instruksi） dan 〜ように言う / 〜ように頼む secara mandiri.",situation:"Situasi komunikasi profesional di Forum koordinasi serikat pekerja dan manajemen perusahaan di ruang konferensi pusat.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜こと（instruksi）!",modelAnswer:"はい、Satoさん！ レポートは来週の金曜日までに提出すること。。",modelAnswerId:"Ya, Sato! Laporan wajib dikumpulkan paling lambat hari Jumat minggu depan..",culturalEtiquette:"Awali pernyataan resmi dengan kedudukan Anda (contoh: Daihyou to shite) agar konteks wewenang dipahami.",skillUnlocked:["Menguasai formulasi pola 〜こと（instruksi）","Mampu menerapkan prinsip koordinasi komunikasi kerja Sudut Pandang, Kedudukan Resmi & Kompensasi"]},pocket_summary:{keyFormula:"〜こと（instruksi） (wajib ... / harus ... (instruksi / aturan tertulis))",coreWords:["出【で】 (asal kelulusan/daerah, keluaran, kelancaran aliran air)","出会い【であい】 (pertemuan pertama kali, perjumpaan berharga)","出合い【であい】 (pertemuan tak terduga, perjumpaan insidental, pertemuan arus)","定期【ていき】 (berkala, waktu teratur, tiket langganan komuter (kereta/bus))"],coreWarning:"Jangan tertukar antara 〜to shite (kapasitas peran) dengan 〜ni totte (sudut pandang evaluatif).",quickDialogue:"A: ブディさん、出の 状況【じょうきょう】は どうです... → B: はい、Satoさん！ レポートは来週の金曜日までに..."}}},i={"les-n3-u18-01":{pedagogical_framework:{what:{summary:"Batasan Wacana, Pergantian Topik & Relasi Sosial (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜一方で, 〜について, 〜によって / 〜による, 〜によると / 〜によれば, 〜だけでなく dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜一方で dan 〜について dalam percakapan kerja wajar.",targetPatterns:["〜一方で (di satu sisi ... di sisi lain ... / sementara itu)","〜について (tentang ... / mengenai topik ...)","〜によって / 〜による (berdasarkan ... / tergantung pada ... / oleh ... / akibat ...)","〜によると / 〜によれば (menurut ... / berdasarkan sumber kabar ...)","〜だけでなく (tidak hanya ... tetapi juga ...)"],coreVocabSample:["なべ","なま","なみ","なみだ","なわ","にち","にちじょう","にっこう"]},sensei_context:{sceneIntro:"Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜一方で dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Batasan Wacana, Pergantian Topik & Relasi Sosial",etiquette:"Gunakan tokorode hanya setelah topik sebelumnya telah tuntas dibahas dan disepakati bersama.",taboos:"Memotong pembicaraan rekan di tengah kalimat dengan tokorode dianggap tidak sopan dalam etika rapat Jepang."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜一方で",moraNote:"Beri jeda bernapas wajar sebelum mengucap tsu-ma-ri untuk menarik perhatian audiens.",soundTip:"Ucapkan 〜一方で dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜一方で",caseScenario:"Menggunakan 〜一方で tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜一方で.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜一方で sesuai kaidah.",explanation:"Kaidah koneksi 〜一方で: Vる / Adj-い / Adj-な + な / N + である + 一方で."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Batasan Wacana, Pergantian Topik & Relasi Sosial (Fondasi & Pemahaman Pola)",setting:"Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo.",narrative:"Budi dan Sato berkoordinasi mengenai alur operasional kerja menggunakan pola 〜一方で."}},dialogue:[{id:"d1",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"ブディさん、鍋の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、鍋の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, nabe no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai panci; hidangan hot pot (nabemono)? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Satoさん！ この仕事は大変な一方で、やりがいもあります。。",furigana:"はい、Satoさん！ この仕事は大変な一方で、やりがいもあります。。",romaji:"Hai, Sato-san! 一方で de susumete imasu.",idText:"Ya, Sato! Pekerjaan ini berat di satu sisi, tetapi di sisi lain juga sangat memuaskan.."},{id:"d3",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"なるほど。日本の文化について研究しています。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。日本の文化について研究しています。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Saya sedang meneliti tentang kebudayaan Jepang.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02034",word:"鍋",reading:"なべ",romaji:"nabe",meaning:"panci; hidangan hot pot (nabemono)",pos:"noun",nuance:"Alat masak berbahan logam, tanah liat, atau keramik yang berbibir dalam untuk merebus atau memasak sup (panci). Selain itu, di Jepang kata 鍋 juga menjadi singkatan lazim untuk hidangan 鍋料理 (nabe-ryouri / hot pot), yaitu tradisi makan bersama di musim dingin di mana aneka sayuran, tahu, dan daging dimasak langsung di atas kompor meja makan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"鍋【なべ】を 確認【かくにん】します。",furigana:"鍋を 確認します。",romaji:"nabe o kakunin shimasu.",idText:"Memeriksa panci; hidangan hot pot (nabemono)."}},{id:"vg-n3-02035",word:"生",reading:"なま",romaji:"nama",meaning:"mentah, segar, langsung (siaran live)",pos:"noun",nuance:"Bermakna: (1) bahan makanan mentah yang belum dimasak dengan api (contoh: 生魚 = ikan mentah/sashimi, 生卵 = telur mentah), (2) belum diawetkan atau baru diperah/segar (contoh: 生ビール = bir segar/draught beer, 生クリーム = krim segar), dan (3) pertunjukan atau siaran langsung secara riil tanpa rekaman tunda (contoh: 生放送 = siaran live, 生演奏 = penampilan musik langsung).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"生【なま】を 確認【かくにん】します。",furigana:"生を 確認します。",romaji:"nama o kakunin shimasu.",idText:"Memeriksa mentah, segar, langsung (siaran live)."}},{id:"vg-n3-02037",word:"波",reading:"なみ",romaji:"nami",meaning:"ombak, gelombang, pasang surut fluktuasi",pos:"noun",nuance:"Merujuk pada gelombang atau ombak di laut, danau, atau perairan. Selain makna fisik air, kata ini sering digunakan secara kiasan untuk menggambarkan pasang surut keadaan emosi, fluktuasi suasana hati, atau tren zaman. Contohnya frasa 時代の波 (gelombang zaman) atau 成績に波がある (nilainya naik-turun berfluktuasi). Berbeda dengan 津波 (tsunami) yang merujuk spesifik pada gelombang raksasa akibat gempa.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"波【なみ】を 確認【かくにん】します。",furigana:"波を 確認します。",romaji:"nami o kakunin shimasu.",idText:"Memeriksa ombak, gelombang, pasang surut fluktuasi."}},{id:"vg-n3-02038",word:"涙",reading:"なみだ",romaji:"namida",meaning:"air mata",pos:"noun",nuance:"Merujuk pada butiran cairan air mata yang menetes karena luapan emosi (kesedihan, rasa haru, kegembiraan mendalam) maupun akibat rangsangan fisik pada mata. Sering dipasangkan dengan verba seperti 涙を流す (meneteskan air mata), 涙が出る (air mata keluar), atau 涙をこらえる (menahan tangis). Berbeda dengan 泣く (naku) yang merupakan perbuatan menangis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"涙【なみだ】を 確認【かくにん】します。",furigana:"涙を 確認します。",romaji:"namida o kakunin shimasu.",idText:"Memeriksa air mata."}},{id:"vg-n3-02040",word:"縄",reading:"なわ",romaji:"nawa",meaning:"tali, tali tambang, tali jerami",pos:"noun",nuance:"Khusus merujuk pada tali tebal yang dipilin dari serat jerami atau rami alami. Berbeda dengan 紐 (himo) yang merujuk pada tali kecil/pipih untuk mengikat pakaian, tali sepatu, atau bingkisan paket, serta ロープ (roopu) yang biasanya terbuat dari serat sintetis kuat. Kata ini sangat lekat dengan permainan tradisional lompat tali yaitu 縄跳び (nawatobi) dan tali suci kuil 注連縄 (shimenawa).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"縄【なわ】を 確認【かくにん】します。",furigana:"縄を 確認します。",romaji:"nawa o kakunin shimasu.",idText:"Memeriksa tali, tali tambang, tali jerami."}},{id:"vg-n3-02046",word:"日",reading:"にち",romaji:"nichi",meaning:"hari, tanggal (penghitung hari)",pos:"counter",nuance:"Sufiks penanggalan kalender serta satuan hitungan kuantitas hari. Pengucapan 'nichi' pada umumnya digunakan mulai dari tanggal 11 dan seterusnya (seperti 十一日, 十五日). Perlu diingat tanggal 1 sampai 10 serta tanggal 14, 20, dan 24 memiliki pembacaan kun'yomi khusus (tsuitachi, futsuka, mikka, hatsuka, dan seterusnya) sehingga tidak boleh dibaca dengan hitungan 'nichi' biasa.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"日【にち】を 確認【かくにん】します。",furigana:"日を 確認します。",romaji:"nichi o kakunin shimasu.",idText:"Memeriksa hari, tanggal (penghitung hari)."}},{id:"vg-n3-02047",word:"日常",reading:"にちじょう",romaji:"nichijou",meaning:"keseharian, sehari-hari, rutinitas harian",pos:"noun",nuance:"Mengacu pada kehidupan biasa yang dijalani hari demi hari secara berulang tanpa perjumpaan istimewa. Sangat jamak dipakai sebagai penerang nomina dengan partikel の (日常会話 / percakapan sehari-hari, 日常生活 / kehidupan rutin harian). Berbeda dengan 普段 (fudan) yang menitikberatkan pada perilaku kebiasaan personal, kata 日常 merangkum keseluruhan ritme realitas lawan dari 非日常 (keadaan liburan atau luar biasa).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"日常【にちじょう】を 確認【かくにん】します。",furigana:"日常を 確認します。",romaji:"nichijou o kakunin shimasu.",idText:"Memeriksa keseharian, sehari-hari, rutinitas harian."}},{id:"vg-n3-02048",word:"日光",reading:"にっこう",romaji:"nikkou",meaning:"sinar matahari, cahaya surya",pos:"noun",nuance:"Istilah formal dan ilmiah untuk mendeskripsikan radiasi pancaran cahaya yang berasal dari sang surya. Sering kali digunakan dalam ranah kesehatan serta ilmu biologi, seperti 日光浴 (berjemur sinar matahari) atau 日光を浴びる (terpapar sinar surya). Berbeda dengan 日差し (hizashi) yang lebih terasa pada sengatan hawa hangatnya, kata 日光 berfokus pada wujud pancaran terangnya cahaya.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"日光【にっこう】を 確認【かくにん】します。",furigana:"日光を 確認します。",romaji:"nikkou o kakunin shimasu.",idText:"Memeriksa sinar matahari, cahaya surya."}}],explanations:[{id:"exp-1",grammarId:"gn3-00113",title:"Pola: 〜一方で",formula:"Vる / Adj-い / Adj-な + な / N + である + 一方で",meaning:"di satu sisi ... di sisi lain ... / sementara itu",nuanceNotes:"〜一方で menghubungkan dua aspek yang kontras atau saling melengkapi dari subjek atau situasi yang sama.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜一方で",idText:"di satu sisi ... di sisi lain ... / sementara itu"}],examples:[{jp:"この仕事は大変な一方で、やりがいもあります。",romaji:"",idText:"Pekerjaan ini berat di satu sisi, tetapi di sisi lain juga sangat memuaskan."},{jp:"科学技術が進歩する一方で、自然環境が破壊されている。",romaji:"",idText:"Di satu sisi sains dan teknologi maju, sementara di sisi lain lingkungan alam dirusak."}]},{id:"exp-2",grammarId:"gn3-00114",title:"Pola: 〜について",formula:"N + について / についての + N",meaning:"tentang ... / mengenai topik ...",nuanceNotes:'〜について menandai pokok pembicaraan, kajian, atau penulisan. "Tentang...", "mengenai...".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜について",idText:"tentang ... / mengenai topik ..."}],examples:[{jp:"日本の文化について研究しています。",romaji:"",idText:"Saya sedang meneliti tentang kebudayaan Jepang."},{jp:"将来の進路について両親と話し合いました。",romaji:"",idText:"Saya telah berdiskusi dengan orang tua mengenai jalur masa depan."}]},{id:"exp-3",grammarId:"gn3-00115",title:"Pola: 〜によって / 〜による",formula:"N + によって / による + N",meaning:"berdasarkan ... / tergantung pada ... / oleh ... / akibat ...",nuanceNotes:"〜によって menyatakan cara/metode, penyebab suatu musibah, keberagaman menurut kelompok, atau pelaku dalam kalimat pasif formal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜によって / 〜による",idText:"berdasarkan ... / tergantung pada ... / oleh ... / akibat ..."}],examples:[{jp:"人によって考え方が違います。",romaji:"",idText:"Tergantung orangnya, cara berpikirnya berbeda-beda."},{jp:"台風によって大きな被害が出ました。",romaji:"",idText:"Akibat angin topan timbul kerusakan besar."},{jp:"インターネットによって多くの情報を得ることができます。",romaji:"",idText:"Melalui internet kita dapat memperoleh banyak informasi."}]},{id:"exp-4",grammarId:"gn3-00116",title:"Pola: 〜によると / 〜によれば",formula:"N + によると / によれば + 〜そうだ / 〜らしい",meaning:"menurut ... / berdasarkan sumber kabar ...",nuanceNotes:"〜によると menyebutkan sumber informasi atau berita yang didengar. Selalu dipasangkan dengan kata kabar seperti 〜そうだ atau 〜ということだ di akhir kalimat.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜によると / 〜によれば",idText:"menurut ... / berdasarkan sumber kabar ..."}],examples:[{jp:"天気予報によると、明日は雨が降るそうです。",romaji:"",idText:"Menurut ramalan cuaca, besok katanya akan turun hujan."},{jp:"ニュースによれば、事故の原因はまだ分かっていない。",romaji:"",idText:"Berdasarkan berita, penyebab kecelakaan masih belum diketahui."}]},{id:"exp-5",grammarId:"gn3-00117",title:"Pola: 〜だけでなく",formula:"V-plain / Adj-い / Adj-な + な / N + だけでなく",meaning:"tidak hanya ... tetapi juga ...",nuanceNotes:'〜だけでなく menyatakan penambahan bahwa hal lain juga berlaku selain hal yang sudah disebutkan. "Tidak hanya A, tetapi juga B".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜だけでなく",idText:"tidak hanya ... tetapi juga ..."}],examples:[{jp:"彼は日本語だけでなく、英語もペラペラです。",romaji:"",idText:"Dia tidak hanya lancar bahasa Jepang, tetapi juga fasih bahasa Inggris."},{jp:"この商品はデザインが良いだけでなく、使いやすい。",romaji:"",idText:"Produk ini tidak hanya desainnya bagus, tetapi juga mudah digunakan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "鍋"?',sentencePrompt:'Makna kata "鍋" (なべ) dalam situasi kerja ini adalah:',options:["panci; hidangan hot pot (nabemono)","mentah, segar, langsung (siaran live)","ombak, gelombang, pasang surut fluktuasi","air mata"],correctAnswer:"panci; hidangan hot pot (nabemono)",explanation:'Makna yang tepat untuk "鍋" adalah "panci; hidangan hot pot (nabemono)".',diagnosticFeedback:{"mentah, segar, langsung (siaran live)":'Salah: Pilihan "mentah, segar, langsung (siaran live)" adalah makna dari kata "生" (なま), bukan arti kata "鍋".',"ombak, gelombang, pasang surut fluktuasi":'Salah: Pilihan "ombak, gelombang, pasang surut fluktuasi" adalah makna dari kata "波" (なみ), bukan arti kata "鍋".',"air mata":'Salah: Pilihan "air mata" adalah makna dari kata "涙" (なみだ), bukan arti kata "鍋".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"この仕事は大変な（　　）、やりがいもあります。",options:["一方で","について","によって / 〜による","というのは"],correctAnswer:"一方で",explanation:'Pola 〜一方で bermakna "di satu sisi ... di sisi lain ... / sementara itu". Kalimat lengkap: "この仕事は大変な一方で、やりがいもあります。".',diagnosticFeedback:{について:'Salah: Pola "について" bermakna "tentang ... / mengenai topik ...", yang tidak sesuai konteks kalimat ini.',"によって / 〜による":'Salah: Pola "によって / 〜による" bermakna "berdasarkan ... / tergantung pada ... / oleh ... / akibat ...", yang tidak sesuai konteks kalimat ini.',というのは:'Salah: Pola "というのは" bermakna "yang disebut ... adalah / maksud dari ... adalah", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜一方で secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["科学技術が進歩する一方で、自然環境が破壊されている。","科学技術が進歩する一方ででした、自然環境が破壊されている。","日本の文化について研究しています。","彼女は去年出かけたきり、戻ってこない。"],correctAnswer:"科学技術が進歩する一方で、自然環境が破壊されている。",explanation:'Kalimat yang benar dan alami adalah "科学技術が進歩する一方で、自然環境が破壊されている。" (Di satu sisi sains dan teknologi maju, sementara di sisi lain lingkungan alam dirusak.).',diagnosticFeedback:{"科学技術が進歩する一方ででした、自然環境が破壊されている。":"Jebakan Konjugasi: Pola 〜一方で membutuhkan aturan sambung (Vる / Adj-い / Adj-な + な / N + である + 一方で), bukan bentuk ini.","日本の文化について研究しています。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜について: tentang ... / mengenai topik ...), bukan kaidah 〜一方で.","彼女は去年出かけたきり、戻ってこない。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜一方で secara tepat (di satu sisi ... di sisi lain ... / sementara itu)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["日本の 文化に ついて 研究しています。","文化に 日本の ついて 研究しています。","日本の ついて 文化に 研究しています。","研究しています。 日本の 文化に ついて"],correctAnswer:"日本の 文化に ついて 研究しています。",explanation:'Susunan yang benar: "日本の 文化に ついて 研究しています。" (Saya sedang meneliti tentang kebudayaan Jepang.).',diagnosticFeedback:{"文化に 日本の ついて 研究しています。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","日本の ついて 文化に 研究しています。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","研究しています。 日本の 文化に ついて":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["日本の","文化に","ついて","研究しています。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo.", saat Sato menyampaikan arahan: 「なるほど。日本の文化について研究しています。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜一方で dan 〜について dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜一方で!",modelAnswer:"はい、Satoさん！ この仕事は大変な一方で、やりがいもあります。。",modelAnswerId:"Ya, Sato! Pekerjaan ini berat di satu sisi, tetapi di sisi lain juga sangat memuaskan..",culturalEtiquette:"Gunakan tokorode hanya setelah topik sebelumnya telah tuntas dibahas dan disepakati bersama.",skillUnlocked:["Menguasai formulasi pola 〜一方で","Mampu menerapkan prinsip koordinasi komunikasi kerja Batasan Wacana, Pergantian Topik & Relasi Sosial"]},pocket_summary:{keyFormula:"〜一方で (di satu sisi ... di sisi lain ... / sementara itu)",coreWords:["鍋【なべ】 (panci; hidangan hot pot (nabemono))","生【なま】 (mentah, segar, langsung (siaran live))","波【なみ】 (ombak, gelombang, pasang surut fluktuasi)","涙【なみだ】 (air mata)"],coreWarning:"Memotong pembicaraan rekan di tengah kalimat dengan tokorode dianggap tidak sopan dalam etika rapat Jepang.",quickDialogue:"A: ブディさん、鍋の 状況【じょうきょう】は どうです... → B: はい、Satoさん！ この仕事は大変な一方で、やり..."}},"les-n3-u18-02":{pedagogical_framework:{what:{summary:"Batasan Wacana, Pergantian Topik & Relasi Sosial (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜も〜ば〜も, 〜らしい, 〜的, 〜ということ dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜も〜ば〜も dan 〜らしい secara mandiri.",targetPatterns:["〜も〜ば〜も (baik ... maupun ... / ada ... dan juga ada ...)","〜らしい (khas ... / benar-benar mencerminkan karakter ...)","〜的 (secara ... / bersifat ... / bernuansa ...)","〜ということ (hal bahwa ... / fakta bahwa ...)"],coreVocabSample:["ひげき","ひざ","ひじょう","びじん","ひたい","ひづけ","ビデオ","ひとこと"]},sensei_context:{sceneIntro:"Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜も〜ば〜も dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Batasan Wacana, Pergantian Topik & Relasi Sosial",etiquette:"Gunakan tokorode hanya setelah topik sebelumnya telah tuntas dibahas dan disepakati bersama.",taboos:"Memotong pembicaraan rekan di tengah kalimat dengan tokorode dianggap tidak sopan dalam etika rapat Jepang."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜も〜ば〜も",moraNote:"Beri jeda bernapas wajar sebelum mengucap tsu-ma-ri untuk menarik perhatian audiens.",soundTip:"Ucapkan 〜も〜ば〜も dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜も〜ば〜も",caseScenario:"Menggunakan 〜も〜ば〜も tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜も〜ば〜も.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜も〜ば〜も sesuai kaidah.",explanation:"Kaidah koneksi 〜も〜ば〜も: N + も + V-ば / Adj-ければ / Adj-なら + N + も."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Batasan Wacana, Pergantian Topik & Relasi Sosial (Produksi Aktif & Aplikasi Nyata)",setting:"Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo.",narrative:"Budi dan Sato berkoordinasi mengenai alur operasional kerja menggunakan pola 〜も〜ば〜も."}},dialogue:[{id:"d1",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"ブディさん、悲劇の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、悲劇の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, higeki no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai tragedi, kisah tragis, malapetaka menyedihkan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Satoさん！ 人生には楽しいこともあれば、苦しいこともある。。",furigana:"はい、Satoさん！ 人生には楽しいこともあれば、苦しいこともある。。",romaji:"Hai, Sato-san! も〜ば〜も de susumete imasu.",idText:"Ya, Sato! Dalam hidup ini ada hal yang menyenangkan, dan ada pula hal yang menyusahkan.."},{id:"d3",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"なるほど。今日は春らしい暖かい日ですね。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。今日は春らしい暖かい日ですね。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Hari ini hari hangat yang sangat khas musim semi ya.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02159",word:"悲劇",reading:"ひげき",romaji:"higeki",meaning:"tragedi, kisah tragis, malapetaka menyedihkan",pos:"noun",nuance:"Genre drama sastra teater yang berakhir menyedihkan/kehancuran tokoh utama (seperti karya Shakespeare), atau dalam pemakaian umum bermakna musibah pahit yang memilukan dalam kehidupan nyata (kolokasi: 悲劇が起こる - terjadi tragedi, 悲劇を繰り返さない - tidak mengulangi tragedi). Lawan kata mutlaknya adalah 喜劇 (kigeki - komedi/lakon gembira).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"悲劇【ひげき】を 確認【かくにん】します。",furigana:"悲劇を 確認します。",romaji:"higeki o kakunin shimasu.",idText:"Memeriksa tragedi, kisah tragis, malapetaka menyedihkan."}},{id:"vg-n3-02161",word:"膝",reading:"ひざ",romaji:"hiza",meaning:"lutut, pangkuan",pos:"noun",nuance:"Bagian anatomi sendi lutut manusia, atau permukaan atas paha saat duduk yang berfungsi sebagai pangkuan (kolokasi: 膝に乗せる - memangku di atas lutut, 膝を曲げる - menekuk lutut, 膝をつく - berlutut). Banyak muncul dalam ungkapan idiomatik seperti 膝を交える (duduk saling merapat berbincang akrab) atau 膝を打つ (menepuk lutut tanda menyadari pemecahan masalah).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"膝【ひざ】を 確認【かくにん】します。",furigana:"膝を 確認します。",romaji:"hiza o kakunin shimasu.",idText:"Memeriksa lutut, pangkuan."}},{id:"vg-n3-02162",word:"非常",reading:"ひじょう",romaji:"hijou",meaning:"keadaan darurat, luar biasa, kegentingan",pos:"noun",nuance:"Arti dasarnya adalah situasi darurat atau kondisi yang tidak normal dan berbahaya (kolokasi: 非常口 - pintu darurat, 非常階段 - tangga darurat, 非常事態 - keadaan darurat siaga, 非常ベル - bel alarm darurat). Bila berimbuhan partikel に (非常に - hijouni), fungsinya beralih menjadi adverbia tingkat tinggi yang bermakna 'amat sangat' (setara とても tetapi bernada lebih formal).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"非常【ひじょう】を 確認【かくにん】します。",furigana:"非常を 確認します。",romaji:"hijou o kakunin shimasu.",idText:"Memeriksa keadaan darurat, luar biasa, kegentingan."}},{id:"vg-n3-02163",word:"美人",reading:"びじん",romaji:"bijin",meaning:"wanita cantik, perempuan berparas jelita",pos:"noun",nuance:"Merujuk kepada wanita yang memiliki keelokan rupa fisik dan daya tarik paras. Biasa digunakan dalam percakapan umum maupun tulisan sastra. Berbeda dengan 美女 (bijo) yang terdengar lebih dramatis atau sastrawi, 美人 sangat lazim dalam kehidupan sehari-hari (misalnya ungkapan 美人画 - lukisan wanita cantik, atau pujian sopan). Antonimnya adalah 不美人 (fubijin).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"美人【びじん】を 確認【かくにん】します。",furigana:"美人を 確認します。",romaji:"bijin o kakunin shimasu.",idText:"Memeriksa wanita cantik, perempuan berparas jelita."}},{id:"vg-n3-02164",word:"額",reading:"ひたい",romaji:"hitai",meaning:"dahi, kening",pos:"noun",nuance:"Bagian kepala antara pangkal rambut dan alis. Kata ひたい (hitai) adalah kata asli bahasa Jepang (kun'yomi) untuk dahi fisik. Istilah bahasa sehari-hari yang sangat akrab adalah おでこ (odeko). Kanji ini bila dibaca がく (gaku) berubah arti menjadi bingkai foto/lukisan atau jumlah uang (金額). Ungkapan terkenal: 額に汗して働く (bekerja membanting tulang hingga dahi berkeringat).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"額【ひたい】を 確認【かくにん】します。",furigana:"額を 確認します。",romaji:"hitai o kakunin shimasu.",idText:"Memeriksa dahi, kening."}},{id:"vg-n3-02165",word:"日付",reading:"ひづけ",romaji:"hidzuke",meaning:"tanggal (penanggalan pada dokumen/surat)",pos:"noun",nuance:"Menyatakan informasi tahun, bulan, dan hari yang tercantum atau dibubuhkan pada surat, formulir, cap pos, atau dokumen resmi (kolokasi: 日付を入れる - membubuhkan tanggal, 日付変更線 - garis tanggal internasional, 日付順 - berurutan berdasarkan tanggal). Berbeda dengan 日時 (nichiji) yang mencakup tanggal sekaligus jam/waktu pelaksanaan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"日付【ひづけ】を 確認【かくにん】します。",furigana:"日付を 確認します。",romaji:"hidzuke o kakunin shimasu.",idText:"Memeriksa tanggal (penanggalan pada dokumen/surat)."}},{id:"vg-n3-02170",word:"ビデオ",reading:"ビデオ",romaji:"bideo",meaning:"video, rekaman video, kaset video",pos:"noun",nuance:"Istilah serapan dari 'video'. Pada awalnya identik dengan kaset rekaman pita VHS dan pemutar VCR (ビデオデッキ), namun seiring perkembangan zaman juga lazim digunakan untuk file rekaman visual digital (kolokasi: ビデオを撮る - merekam video, ビデオ通話 - panggilan video/video call). Kata 動画 (douga) kini lebih sering dipakai untuk konten video internet/streaming.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ビデオを 確認【かくにん】します。",furigana:"ビデオを 確認します。",romaji:"bideo o kakunin shimasu.",idText:"Memeriksa video, rekaman video, kaset video."}},{id:"vg-n3-02171",word:"一言",reading:"ひとこと",romaji:"hitokoto",meaning:"sepatah kata, sepatah dua patah kata, komentar singkat",pos:"noun",nuance:"Bermakna satu kata pendek atau sambutan singkat (kolokasi: 一言お礼を言う - mengucap sepatah kata terima kasih, 一言挨拶 - sambutan singkat, 一言多い - terlalu banyak omong/kelepasan kata yang tak perlu). Sangat penting dalam etika sosial Jepang di mana 'sepatah kata pemberitahuan awal' (一言断りを入れる) dapat mencegah kesalahpahaman.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"一言【ひとこと】を 確認【かくにん】します。",furigana:"一言を 確認します。",romaji:"hitokoto o kakunin shimasu.",idText:"Memeriksa sepatah kata, sepatah dua patah kata, komentar singkat."}}],explanations:[{id:"exp-1",grammarId:"gn3-00118",title:"Pola: 〜も〜ば〜も",formula:"N + も + V-ば / Adj-ければ / Adj-なら + N + も",meaning:"baik ... maupun ... / ada ... dan juga ada ...",nuanceNotes:'〜も〜ば〜も menyebutkan dua hal yang berdampingan atau beraneka ragam. "Baik hal positif maupun negatif, ada semuanya".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜も〜ば〜も",idText:"baik ... maupun ... / ada ... dan juga ada ..."}],examples:[{jp:"人生には楽しいこともあれば、苦しいこともある。",romaji:"",idText:"Dalam hidup ini ada hal yang menyenangkan, dan ada pula hal yang menyusahkan."},{jp:"この店は料理もおいしければ、サービスもいい。",romaji:"",idText:"Toko ini makanannya enak, pelayanannya pun ramah."}]},{id:"exp-2",grammarId:"gn3-00119",title:"Pola: 〜らしい",formula:"N + らしい",meaning:"khas ... / benar-benar mencerminkan karakter ...",nuanceNotes:'〜らしい menyatakan bahwa sesuatu memiliki kualitas sejati yang khas dan mencerminkan sifat hakiki dari kata benda tersebut. "Sangat khas...", "layaknya...".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜らしい",idText:"khas ... / benar-benar mencerminkan karakter ..."}],examples:[{jp:"今日は春らしい暖かい日ですね。",romaji:"",idText:"Hari ini hari hangat yang sangat khas musim semi ya."},{jp:"男らしく堂々としていなさい。",romaji:"",idText:"Tegap dan percaya dirilah layaknya seorang pria sejati."}]},{id:"exp-3",grammarId:"gn3-00120",title:"Pola: 〜的",formula:"N + 的（な/に/だ）",meaning:"secara ... / bersifat ... / bernuansa ...",nuanceNotes:'〜的な adalah akhiran pembentuk kata sifat atau kata keterangan yang bermakna "bersifat", "berkaitan dengan", atau "secara...".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜的",idText:"secara ... / bersifat ... / bernuansa ..."}],examples:[{jp:"これらは基本的な文法規則です。",romaji:"",idText:"Ini adalah aturan-aturan tata bahasa yang bersifat mendasar."},{jp:"健康的な生活を心がけています。",romaji:"",idText:"Saya berusaha menjalani gaya hidup yang sehat."},{jp:"経済的に自立したい。",romaji:"",idText:"Saya ingin mandiri secara finansial/ekonomi."}]},{id:"exp-4",grammarId:"gn3-00063",title:"Pola: 〜ということ",formula:"V/Adj plain / N + ということ",meaning:"hal bahwa ... / fakta bahwa ...",nuanceNotes:'〜ということ mengubah klausa menjadi nomina yang lebih abstrak atau umum: "hal bahwa", "fakta bahwa".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ということ",idText:"hal bahwa ... / fakta bahwa ..."}],examples:[{jp:"彼が来ないということを、みんなに伝えてください。",romaji:"",idText:"Tolong sampaikan kepada semua orang bahwa dia tidak akan datang."},{jp:"諦めないということが大切です。",romaji:"",idText:"Hal bahwa kita tidak menyerah itu penting."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "悲劇"?',sentencePrompt:'Makna kata "悲劇" (ひげき) dalam situasi kerja ini adalah:',options:["tragedi, kisah tragis, malapetaka menyedihkan","lutut, pangkuan","keadaan darurat, luar biasa, kegentingan","wanita cantik, perempuan berparas jelita"],correctAnswer:"tragedi, kisah tragis, malapetaka menyedihkan",explanation:'Makna yang tepat untuk "悲劇" adalah "tragedi, kisah tragis, malapetaka menyedihkan".',diagnosticFeedback:{"lutut, pangkuan":'Salah: Pilihan "lutut, pangkuan" adalah makna dari kata "膝" (ひざ), bukan arti kata "悲劇".',"keadaan darurat, luar biasa, kegentingan":'Salah: Pilihan "keadaan darurat, luar biasa, kegentingan" adalah makna dari kata "非常" (ひじょう), bukan arti kata "悲劇".',"wanita cantik, perempuan berparas jelita":'Salah: Pilihan "wanita cantik, perempuan berparas jelita" adalah makna dari kata "美人" (びじん), bukan arti kata "悲劇".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"人生には楽しいこと（　　）、苦しいこと（　　）。",options:["もあれば","らしい","的","というのは"],correctAnswer:"もあれば",explanation:'Pola 〜も〜ば〜も bermakna "baik ... maupun ... / ada ... dan juga ada ...". Kalimat lengkap: "人生には楽しいこともあれば、苦しいこともある。".',diagnosticFeedback:{らしい:'Salah: Pola "らしい" bermakna "khas ... / benar-benar mencerminkan karakter ...", yang tidak sesuai konteks kalimat ini.',的:'Salah: Pola "的" bermakna "secara ... / bersifat ... / bernuansa ...", yang tidak sesuai konteks kalimat ini.',というのは:'Salah: Pola "というのは" bermakna "yang disebut ... adalah / maksud dari ... adalah", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜も〜ば〜も secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["この店は料理もおいしければ、サービスもいい。","この店は料理もおいしければ、サービスもいい。でした","今日は春らしい暖かい日ですね。","彼女は去年出かけたきり、戻ってこない。"],correctAnswer:"この店は料理もおいしければ、サービスもいい。",explanation:'Kalimat yang benar dan alami adalah "この店は料理もおいしければ、サービスもいい。" (Toko ini makanannya enak, pelayanannya pun ramah.).',diagnosticFeedback:{"この店は料理もおいしければ、サービスもいい。でした":"Jebakan Konjugasi: Pola 〜も〜ば〜も membutuhkan aturan sambung (N + も + V-ば / Adj-ければ / Adj-なら + N + も), bukan bentuk ini.","今日は春らしい暖かい日ですね。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜らしい: khas ... / benar-benar mencerminkan karakter ...), bukan kaidah 〜も〜ば〜も.","彼女は去年出かけたきり、戻ってこない。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜も〜ば〜も secara tepat (baik ... maupun ... / ada ... dan juga ada ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["今日は 春らしい 暖かい 日ですね。","春らしい 今日は 暖かい 日ですね。","今日は 暖かい 春らしい 日ですね。","日ですね。 今日は 春らしい 暖かい"],correctAnswer:"今日は 春らしい 暖かい 日ですね。",explanation:'Susunan yang benar: "今日は 春らしい 暖かい 日ですね。" (Hari ini hari hangat yang sangat khas musim semi ya.).',diagnosticFeedback:{"春らしい 今日は 暖かい 日ですね。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","今日は 暖かい 春らしい 日ですね。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","日ですね。 今日は 春らしい 暖かい":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["今日は","春らしい","暖かい","日ですね。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo.", saat Sato menyampaikan arahan: 「なるほど。今日は春らしい暖かい日ですね。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜も〜ば〜も dan 〜らしい secara mandiri.",situation:"Situasi komunikasi profesional di Rapat koordinasi mingguan lintas divisi operasional kantor cabang Tokyo.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜も〜ば〜も!",modelAnswer:"はい、Satoさん！ 人生には楽しいこともあれば、苦しいこともある。。",modelAnswerId:"Ya, Sato! Dalam hidup ini ada hal yang menyenangkan, dan ada pula hal yang menyusahkan..",culturalEtiquette:"Gunakan tokorode hanya setelah topik sebelumnya telah tuntas dibahas dan disepakati bersama.",skillUnlocked:["Menguasai formulasi pola 〜も〜ば〜も","Mampu menerapkan prinsip koordinasi komunikasi kerja Batasan Wacana, Pergantian Topik & Relasi Sosial"]},pocket_summary:{keyFormula:"〜も〜ば〜も (baik ... maupun ... / ada ... dan juga ada ...)",coreWords:["悲劇【ひげき】 (tragedi, kisah tragis, malapetaka menyedihkan)","膝【ひざ】 (lutut, pangkuan)","非常【ひじょう】 (keadaan darurat, luar biasa, kegentingan)","美人【びじん】 (wanita cantik, perempuan berparas jelita)"],coreWarning:"Memotong pembicaraan rekan di tengah kalimat dengan tokorode dianggap tidak sopan dalam etika rapat Jepang.",quickDialogue:"A: ブディさん、悲劇の 状況【じょうきょう】は どうで... → B: はい、Satoさん！ 人生には楽しいこともあれば、..."}}},t={"les-n3-u19-01":{pedagogical_framework:{what:{summary:"Laporan Wacana, Kutipan Berita & Informasi Resmi (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜というのは, 〜のを, 〜み (nominalisasi adjektif), 〜において / 〜における, 〜に関して dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜というのは dan 〜のを dalam percakapan kerja wajar.",targetPatterns:["〜というのは (yang disebut ... adalah / maksud dari ... adalah)","〜のを (hal ... / tindakan ... (nominalisasi objek))","〜み (nominalisasi adjektif) (rasa ... / kesan ... (nominalisasi adjektif))","〜において / 〜における (di ... / dalam ... (formal))","〜に関して (berkenaan dengan ... / terkait dengan ...)"],coreVocabSample:["ほうせき","ボーイ","ボート","ホーム","ボール","ほか","ほこり","ほこり"]},sensei_context:{sceneIntro:"Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜というのは dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Laporan Wacana, Kutipan Berita & Informasi Resmi",etiquette:"Selalu sebutkan sumber informasi awal saat meneruskan kabar agar tidak menimbulkan rumor kerja.",taboos:"Jangan menggunakan ragam kasual 〜datte saat menyampaikan pengumuman resmi dari direksi."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜というのは",moraNote:"Lafalkan to no koto da dengan nada heiban objektif dan pelafalan stabil.",soundTip:"Ucapkan 〜というのは dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜というのは",caseScenario:"Menggunakan 〜というのは tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜というのは.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜というのは sesuai kaidah.",explanation:"Kaidah koneksi 〜というのは: N / 「...」 + というのは + 文."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Laporan Wacana, Kutipan Berita & Informasi Resmi (Fondasi & Pemahaman Pola)",setting:"Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional.",narrative:"Budi dan Sato berkoordinasi mengenai alur operasional kerja menggunakan pola 〜というのは."}},dialogue:[{id:"d1",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"ブディさん、宝石の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、宝石の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, houseki no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai batu permata, batu mulia? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Satoさん！ 「武士道」というのは、侍の倫理規範のことです。。",furigana:"はい、Satoさん！ 「武士道」というのは、侍の倫理規範のことです。。",romaji:"Hai, Sato-san! というのは de susumete imasu.",idText:'Ya, Sato! "Bushido" adalah norma etika para samurai..'},{id:"d3",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"なるほど。彼が走っているのを見た。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。彼が走っているのを見た。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Saya melihat dia sedang berlari.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02258",word:"宝石",reading:"ほうせき",romaji:"houseki",meaning:"batu permata, batu mulia",pos:"noun",nuance:"Batu mineral langka bernilai tinggi yang diasah dan dipoles dengan sangat indah untuk dijadikan perhiasan mewah, seperti intan/berlian, mirah delima, dan safir (宝石店 toko permata, 宝石箱 kotak permata). Berbeda dengan 石 (ishi) yang merupakan batu biasa di alam bebas.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"宝石【ほうせき】を 確認【かくにん】します。",furigana:"宝石を 確認します。",romaji:"houseki o kakunin shimasu.",idText:"Memeriksa batu permata, batu mulia."}},{id:"vg-n3-02263",word:"ボーイ",reading:"ボーイ",romaji:"booi",meaning:"pelayan hotel pria, bellboy, pesuruh",pos:"noun",nuance:'Kata serapan dari bahasa Inggris "boy". Dalam konteks Jepang modern, kata ini sering merujuk pada petugas pelayan pria di hotel yang membawakan koper bawaan tamu (bellboy / porter), atau staf pria pelayan meja di restoran/klub. Berbeda dengan kata 男の子 (otokonoko) bila semata-mata mengartikan anak laki-laki.',particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ボーイを 確認【かくにん】します。",furigana:"ボーイを 確認します。",romaji:"booi o kakunin shimasu.",idText:"Memeriksa pelayan hotel pria, bellboy, pesuruh."}},{id:"vg-n3-02264",word:"ボート",reading:"ボート",romaji:"booto",meaning:"perahu kecil, perahu dayung, boat",pos:"noun",nuance:"Perahu kecil tak beratap yang digerakkan menggunakan kayuh dayung (手漕ぎボート) atau mesin motor kecil (モーターボート) di danau, sungai tenang, atau teluk untuk rekreasi atau cabang olahraga dayung beregu. Berbeda dengan 船 (fune) yang merupakan istilah umum luas termasuk kapal muatan besar.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ボートを 確認【かくにん】します。",furigana:"ボートを 確認します。",romaji:"booto o kakunin shimasu.",idText:"Memeriksa perahu kecil, perahu dayung, boat."}},{id:"vg-n3-02265",word:"ホーム",reading:"ホーム",romaji:"hoomu",meaning:"peron stasiun, panti, tempat berteduh",pos:"noun",nuance:'Memiliki dua pemakaian utama dalam bahasa Jepang: (1) singkatan populer dari プラットホーム (peron tempat penumpang naik/turun di stasiun kereta); (2) serapan dari bahasa Inggris "home" yang merujuk pada panti wreda (老人ホーム panti jompo) atau suasana markas sendiri dalam olahraga (ホームゲーム laga kandang).',particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ホームを 確認【かくにん】します。",furigana:"ホームを 確認します。",romaji:"hoomu o kakunin shimasu.",idText:"Memeriksa peron stasiun, panti, tempat berteduh."}},{id:"vg-n3-02266",word:"ボール",reading:"ボール",romaji:"booru",meaning:"bola mainan, mangkuk adonan dapur",pos:"noun",nuance:"Dapat merujuk pada dua benda berbeda tergantung konteks: (1) bola bundar yang dipakai dalam aneka cabang olahraga seperti sepak bola, tenis, atau bisbol (ボールを蹴る menendang bola); (2) mangkuk cekung dari bahan kaca atau baja nirkarat untuk mencampur adonan kue/masakan di dapur (juga sering dieja ボウル).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ボールを 確認【かくにん】します。",furigana:"ボールを 確認します。",romaji:"booru o kakunin shimasu.",idText:"Memeriksa bola mainan, mangkuk adonan dapur."}},{id:"vg-n3-02267",word:"他",reading:"ほか",romaji:"hoka",meaning:"yang lain, selain itu, di luar itu",pos:"noun",nuance:"Menunjuk pada benda, orang, atau tempat di luar hal yang sedang menjadi fokus (misal 他の人 orang lain, 他の店 toko lain). Sangat lazim dipakai dalam struktur tata bahasa penting seperti 〜の他に (selain...) atau 〜より他にない / 〜ほかない (tidak ada pilihan lain selain...). Berbeda dengan 別 (betsu) yang lebih menekankan sifat terpisah atau beda kategori.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"他【ほか】を 確認【かくにん】します。",furigana:"他を 確認します。",romaji:"hoka o kakunin shimasu.",idText:"Memeriksa yang lain, selain itu, di luar itu."}},{id:"vg-n3-02268",word:"誇り",reading:"ほこり",romaji:"hokori",meaning:"kebanggaan, rasa bangga, harga diri luhur",pos:"noun",nuance:"Bentuk nomina dari kata kerja 誇る (hokoru). Mengungkapkan rasa puas, terhormat, dan bangga atas kemampuan, karya, keluarga, atau bangsanya sendiri (誇りを持つ memiliki rasa bangga, 誇りに思う merasa bangga). Homofon dengan kata 埃 (ほこり / debu), namun kanji dan artinya bertolak belakang.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"誇り【ほこり】を 確認【かくにん】します。",furigana:"誇りを 確認します。",romaji:"hokori o kakunin shimasu.",idText:"Memeriksa kebanggaan, rasa bangga, harga diri luhur."}},{id:"vg-n3-02269",word:"埃",reading:"ほこり",romaji:"hokori",meaning:"debu, partikel kotoran kering",pos:"noun",nuance:"Partikel kotoran sangat halus yang melayang di udara dan mengendap di atas lantai, meja, atau buku yang jarang dibersihkan (埃を払う mengibaskan debu, 埃をかぶる terselimuti debu). Homofon dengan 誇り (kebanggaan), namun kanji 埃 berunsur tanah (土).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"埃【ほこり】を 確認【かくにん】します。",furigana:"埃を 確認します。",romaji:"hokori o kakunin shimasu.",idText:"Memeriksa debu, partikel kotoran kering."}}],explanations:[{id:"exp-1",grammarId:"gn3-00064",title:"Pola: 〜というのは",formula:"N / 「...」 + というのは + 文",meaning:"yang disebut ... adalah / maksud dari ... adalah",nuanceNotes:"〜というのは digunakan untuk mendefinisikan atau menjelaskan suatu istilah atau pernyataan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜というのは",idText:"yang disebut ... adalah / maksud dari ... adalah"}],examples:[{jp:"「武士道」というのは、侍の倫理規範のことです。",romaji:"",idText:'"Bushido" adalah norma etika para samurai.'},{jp:"行きたくないというのは、本当ですか。",romaji:"",idText:"Apakah benar bahwa kamu tidak mau pergi?"}]},{id:"exp-2",grammarId:"gn3-00097",title:"Pola: 〜のを",formula:"V + の + を + V",meaning:"hal ... / tindakan ... (nominalisasi objek)",nuanceNotes:"〜のを menominalisasi klausa verba dan menjadikannya objek dari verba lain. Sering dengan verba persepsi (見る, 聞く, 知る) atau verba emosi.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜のを",idText:"hal ... / tindakan ... (nominalisasi objek)"}],examples:[{jp:"彼が走っているのを見た。",romaji:"",idText:"Saya melihat dia sedang berlari."},{jp:"財布を落としたのを気づかなかった。",romaji:"",idText:"Tidak menyadari bahwa dompet terjatuh."}]},{id:"exp-3",grammarId:"gn3-00103",title:"Pola: 〜み (nominalisasi adjektif)",formula:"Adj-i語幹 + み",meaning:"rasa ... / kesan ... (nominalisasi adjektif)",nuanceNotes:"〜み mengubah adjektif menjadi nomina yang menyatakan kualitas atau kesan yang dirasakan. Berbeda dari さ yang lebih objektif.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜み (nominalisasi adjektif)",idText:"rasa ... / kesan ... (nominalisasi adjektif)"}],examples:[{jp:"この物語には深みがある。",romaji:"",idText:"Kisah ini punya kedalaman."},{jp:"子どもらしいかわいらしみがあります。",romaji:"",idText:"Ada kepolosan yang menggemaskan khas anak-anak."}]},{id:"exp-4",grammarId:"gn3-00048",title:"Pola: 〜において / 〜における",formula:"N + において / N + における + N",meaning:"di ... / dalam ... (formal)",nuanceNotes:"〜において adalah bentuk formal dari で atau に, menandai tempat, waktu, atau bidang. 〜における + N digunakan sebagai modifier nomina.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜において / 〜における",idText:"di ... / dalam ... (formal)"}],examples:[{jp:"スポーツにおいて、努力は不可欠だ。",romaji:"",idText:"Dalam olahraga, usaha keras tidak bisa ditinggalkan."},{jp:"現代社会における問題について話し合った。",romaji:"",idText:"Mendiskusikan masalah-masalah dalam masyarakat modern."}]},{id:"exp-5",grammarId:"gn3-00049",title:"Pola: 〜に関して",formula:"N + に関して / に関する + N",meaning:"berkenaan dengan ... / terkait dengan ...",nuanceNotes:'〜に関して adalah bentuk lebih formal dari について: "berkenaan dengan", "terkait". Sering digunakan dalam konteks resmi atau tulisan.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に関して",idText:"berkenaan dengan ... / terkait dengan ..."}],examples:[{jp:"今回の事故に関して、調査が行われています。",romaji:"",idText:"Terkait kecelakaan kali ini, sedang dilakukan penyelidikan."},{jp:"環境問題に関するレポートを書きました。",romaji:"",idText:"Saya menulis laporan berkenaan dengan masalah lingkungan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "宝石"?',sentencePrompt:'Makna kata "宝石" (ほうせき) dalam situasi kerja ini adalah:',options:["batu permata, batu mulia","pelayan hotel pria, bellboy, pesuruh","perahu kecil, perahu dayung, boat","peron stasiun, panti, tempat berteduh"],correctAnswer:"batu permata, batu mulia",explanation:'Makna yang tepat untuk "宝石" adalah "batu permata, batu mulia".',diagnosticFeedback:{"pelayan hotel pria, bellboy, pesuruh":'Salah: Pilihan "pelayan hotel pria, bellboy, pesuruh" adalah makna dari kata "ボーイ" (ボーイ), bukan arti kata "宝石".',"perahu kecil, perahu dayung, boat":'Salah: Pilihan "perahu kecil, perahu dayung, boat" adalah makna dari kata "ボート" (ボート), bukan arti kata "宝石".',"peron stasiun, panti, tempat berteduh":'Salah: Pilihan "peron stasiun, panti, tempat berteduh" adalah makna dari kata "ホーム" (ホーム), bukan arti kata "宝石".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"「武士道」（　　）、侍の倫理規範のことです。",options:["というのは","のを","み (nominalisasi adjektif)","させていただく"],correctAnswer:"というのは",explanation:'Pola 〜というのは bermakna "yang disebut ... adalah / maksud dari ... adalah". Kalimat lengkap: "「武士道」というのは、侍の倫理規範のことです。".',diagnosticFeedback:{のを:'Salah: Pola "のを" bermakna "hal ... / tindakan ... (nominalisasi objek)", yang tidak sesuai konteks kalimat ini.',"み (nominalisasi adjektif)":'Salah: Pola "み (nominalisasi adjektif)" bermakna "rasa ... / kesan ... (nominalisasi adjektif)", yang tidak sesuai konteks kalimat ini.',させていただく:'Salah: Pola "させていただく" bermakna "saya mohon izin untuk ..., saya berani ... (keigo rendah hati)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜というのは secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["行きたくないというのは、本当ですか。","行きたくないというのはでした、本当ですか。","彼が走っているのを見た。","よく考えたうえで、決断します。"],correctAnswer:"行きたくないというのは、本当ですか。",explanation:'Kalimat yang benar dan alami adalah "行きたくないというのは、本当ですか。" (Apakah benar bahwa kamu tidak mau pergi?).',diagnosticFeedback:{"行きたくないというのはでした、本当ですか。":"Jebakan Konjugasi: Pola 〜というのは membutuhkan aturan sambung (N / 「...」 + というのは + 文), bukan bentuk ini.","彼が走っているのを見た。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜のを: hal ... / tindakan ... (nominalisasi objek)), bukan kaidah 〜というのは.","よく考えたうえで、決断します。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜というのは secara tepat (yang disebut ... adalah / maksud dari ... adalah)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["彼が走 っている のを見た 。","っている 彼が走 のを見た 。","彼が走 のを見た っている 。","。 彼が走 っている のを見た"],correctAnswer:"彼が走 っている のを見た 。",explanation:'Susunan yang benar: "彼が走 っている のを見た 。" (Saya melihat dia sedang berlari.).',diagnosticFeedback:{"っている 彼が走 のを見た 。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","彼が走 のを見た っている 。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","。 彼が走 っている のを見た":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["彼が走","っている","のを見た","。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional.", saat Sato menyampaikan arahan: 「なるほど。彼が走っているのを見た。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜というのは dan 〜のを dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜というのは!",modelAnswer:"はい、Satoさん！ 「武士道」というのは、侍の倫理規範のことです。。",modelAnswerId:'Ya, Sato! "Bushido" adalah norma etika para samurai..',culturalEtiquette:"Selalu sebutkan sumber informasi awal saat meneruskan kabar agar tidak menimbulkan rumor kerja.",skillUnlocked:["Menguasai formulasi pola 〜というのは","Mampu menerapkan prinsip koordinasi komunikasi kerja Laporan Wacana, Kutipan Berita & Informasi Resmi"]},pocket_summary:{keyFormula:"〜というのは (yang disebut ... adalah / maksud dari ... adalah)",coreWords:["宝石【ほうせき】 (batu permata, batu mulia)","ボーイ【ボーイ】 (pelayan hotel pria, bellboy, pesuruh)","ボート【ボート】 (perahu kecil, perahu dayung, boat)","ホーム【ホーム】 (peron stasiun, panti, tempat berteduh)"],coreWarning:"Jangan menggunakan ragam kasual 〜datte saat menyampaikan pengumuman resmi dari direksi.",quickDialogue:"A: ブディさん、宝石の 状況【じょうきょう】は どうで... → B: はい、Satoさん！ 「武士道」というのは、侍の倫..."}},"les-n3-u19-02":{pedagogical_framework:{what:{summary:"Laporan Wacana, Kutipan Berita & Informasi Resmi (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜ますように / 〜ませんように, 〜といいなあ / 〜たらいいなあ, 〜てほしい, 〜てもらいたい dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜ますように / 〜ませんように dan 〜といいなあ / 〜たらいいなあ secara mandiri.",targetPatterns:["〜ますように / 〜ませんように (semoga ... / mudah-mudahan ...)","〜といいなあ / 〜たらいいなあ (alangkah baiknya kalau ... / andai bisa ...)","〜てほしい (ingin agar seseorang melakukan ...)","〜てもらいたい (ingin meminta seseorang melakukan ... (formal))"],coreVocabSample:["デザート","でんごん","と","とう","どうし","どうし","とも","なみ"]},sensei_context:{sceneIntro:"Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜ますように / 〜ませんように dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Laporan Wacana, Kutipan Berita & Informasi Resmi",etiquette:"Selalu sebutkan sumber informasi awal saat meneruskan kabar agar tidak menimbulkan rumor kerja.",taboos:"Jangan menggunakan ragam kasual 〜datte saat menyampaikan pengumuman resmi dari direksi."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ますように / 〜ませんように",moraNote:"Lafalkan to no koto da dengan nada heiban objektif dan pelafalan stabil.",soundTip:"Ucapkan 〜ますように / 〜ませんように dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ますように / 〜ませんように",caseScenario:"Menggunakan 〜ますように / 〜ませんように tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ますように / 〜ませんように.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ますように / 〜ませんように sesuai kaidah.",explanation:"Kaidah koneksi 〜ますように / 〜ませんように: V-ます / V-ません + ように."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Laporan Wacana, Kutipan Berita & Informasi Resmi (Produksi Aktif & Aplikasi Nyata)",setting:"Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional.",narrative:"Budi dan Sato berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ますように / 〜ませんように."}},dialogue:[{id:"d1",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"ブディさん、デザートの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、デザートの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, dezaato no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai hidangan penutup, makanan pencuci mulut? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Satoさん！ 試験に合格しますように。。",furigana:"はい、Satoさん！ 試験に合格しますように。。",romaji:"Hai, Sato-san! ますように / 〜ませんように de susumete imasu.",idText:"Ya, Sato! Semoga lulus ujian.."},{id:"d3",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"なるほど。明日晴れるといいなあ。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。明日晴れるといいなあ。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Alangkah baiknya kalau besok cerah.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02375",word:"デザート",reading:"デザート",romaji:"dezaato",meaning:"hidangan penutup, makanan pencuci mulut",pos:"noun",nuance:"Serapan dari kata 'dessert'. Makanan manis seperti es krim, puding, kue tart, atau buah segar yang dinikmati setelah selesai menyantap hidangan utama (デザートを食べる / 食後のデザート). Berbeda dengan おやつ / お菓子 (camilan/kudapan yang bisa dimakan kapan saja di luar jam makan utama).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"デザートを 確認【かくにん】します。",furigana:"デザートを 確認します。",romaji:"dezaato o kakunin shimasu.",idText:"Memeriksa hidangan penutup, makanan pencuci mulut."}},{id:"vg-n3-02377",word:"伝言",reading:"でんごん",romaji:"dengon",meaning:"pesan lisan, titipan pesan",pos:"noun",nuance:"Menitipkan pesan verbal melalui perantara (rekan kerja, sekretaris, atau mesin penjawab telepon) untuk diteruskan kepada orang yang sedang tidak bisa dihubungi langsung (misal 伝言をお願いできますか bolehkah saya menitip pesan?, 伝言を承る menerima titipan pesan). Berbeda dengan メモ (catatan kertas tertulis) atau 手紙 (surat).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"伝言【でんごん】を 確認【かくにん】します。",furigana:"伝言を 確認します。",romaji:"dengon o kakunin shimasu.",idText:"Memeriksa pesan lisan, titipan pesan."}},{id:"vg-n3-02378",word:"と",reading:"と",romaji:"to",meaning:"dan (menyebutkan semua benda tuntas); bersama; dengan; jika / begitu (syarat mutlak/hasil niscaya)",pos:"particle",nuance:"Partikel multifungsi berbobot tinggi: (1) penghubung kata benda secara lengkap tanpa menyisakan yang lain (リンゴとミカン apel dan jeruk); (2) penanda rekan kebersamaan (友達と話す berbicara dengan teman); (3) penanda kutipan ujaran/pikiran (〜と言う, 〜と思う); (4) konjungsi syarat niscaya/alamiah di mana kalimat kedua pasti otomatis terjadi jika klausa pertama terpenuhi (ボタンを押すと切符が出る jika menekan tombol, tiket keluar; 春になると暖かくなる begitu tiba musim semi, udara menghangat). Berbeda dengan や (menyebutkan sebagian) dan たら/ば (pengandaian hipotesis).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"とを 確認【かくにん】します。",furigana:"とを 確認します。",romaji:"to o kakunin shimasu.",idText:"Memeriksa dan (menyebutkan semua benda tuntas); bersama; dengan; jika / begitu (syarat mutlak/hasil niscaya)."}},{id:"vg-n3-02380",word:"棟",reading:"とう",romaji:"tou",meaning:"gedung, blok bangunan; kata bantu hitung untuk bangunan/rumah",pos:"noun",nuance:"Digunakan sebagai penanda blok gedung/sayap bangunan tertentu pada kompleks kampus atau apartemen (misal A棟 blok A, 研究棟 gedung penelitian, 管理棟 gedung administrasi). Juga sangat umum berfungsi sebagai kata bantu hitung (counter) untuk unit bangunan fisik yang berdiri utuh (misalnya マンション３棟 tiga blok gedung apartemen, 住宅一棟 satu unit rumah). Jika dibaca 'mune', merujuk pada bubungan atap rumah tradisional.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"棟【とう】を 確認【かくにん】します。",furigana:"棟を 確認します。",romaji:"tou o kakunin shimasu.",idText:"Memeriksa gedung, blok bangunan; kata bantu hitung untuk bangunan/rumah."}},{id:"vg-n3-02382",word:"同士",reading:"どうし",romaji:"doushi",meaning:"sesama, antar- (sesama anggota kategori yang sama), satu sama lain",pos:"noun",nuance:"Dilekatkan langsung di belakang kata benda orang atau kelompok untuk menyatakan hubungan kesetaraan antarsesama yang berada dalam kelompok, profesi, atau kondisi yang sama (misalnya 友達同士 antar sesama teman, 若者同士 antar sesama anak muda, 恋人同士 sepasang kekasih). Sering dipakai dalam pola 〜同士で (di antara sesama...). Berbeda dengan 同志 (doushi - rekan seperjuangan yang berbagi ideologi/visi luhur).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"同士【どうし】を 確認【かくにん】します。",furigana:"同士を 確認します。",romaji:"doushi o kakunin shimasu.",idText:"Memeriksa sesama, antar- (sesama anggota kategori yang sama), satu sama lain."}},{id:"vg-n3-02383",word:"同志",reading:"どうし",romaji:"doushi",meaning:"rekan seperjuangan, kawan sevisi, sahabat satu cita-cita",pos:"noun",nuance:"Menyebut orang-orang yang memiliki aspirasi, visi kemanusiaan, atau tekad perjuangan ideologis yang seirama (志を同じくする人). Memiliki nuansa emosional ikatan batin yang sangat kokoh dalam pergerakan reformasi, perjuangan revolusi, atau pendirian rintisan visi baru. Berbeda dengan 同士 (doushi - antarsesama kategori netral).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"同志【どうし】を 確認【かくにん】します。",furigana:"同志を 確認します。",romaji:"doushi o kakunin shimasu.",idText:"Memeriksa rekan seperjuangan, kawan sevisi, sahabat satu cita-cita."}},{id:"vg-n3-02387",word:"供",reading:"とも",romaji:"tomo",meaning:"pengikut, pendamping, teman perjalanan",pos:"noun",nuance:"Merujuk pada orang yang menemani atau menyertai seseorang dalam suatu perjalanan atau kegiatan, sangat sering hadir dalam bentuk sopan お供 (otomo) atau verba お供する (otomo suru - menyertai). Berbeda dengan 友達 (sahabat sejajar), 供 mengandung kesan mendampingi atau menyertai pihak utama.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"供【とも】を 確認【かくにん】します。",furigana:"供を 確認します。",romaji:"tomo o kakunin shimasu.",idText:"Memeriksa pengikut, pendamping, teman perjalanan."}},{id:"vg-n3-02388",word:"並",reading:"なみ",romaji:"nami",meaning:"biasa, sedang, standar porsi menengah",pos:"noun",nuance:"Menunjukkan ukuran atau tingkatan rata-rata yang berada di tengah standar umum, lazim digunakan untuk porsi sedang di restoran Jepang (contoh: 並盛り porsi sedang, lawan dari 大盛り porsi besar). Bisa pula melekat sebagai sufiks yang bermakna setara orang biasa (misalnya 人並み).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"並【なみ】を 確認【かくにん】します。",furigana:"並を 確認します。",romaji:"nami o kakunin shimasu.",idText:"Memeriksa biasa, sedang, standar porsi menengah."}}],explanations:[{id:"exp-1",grammarId:"gn3-00078",title:"Pola: 〜ますように / 〜ませんように",formula:"V-ます / V-ません + ように",meaning:"semoga ... / mudah-mudahan ...",nuanceNotes:'〜ますように digunakan untuk berdoa atau mengungkapkan harapan: "semoga", "mudah-mudahan".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ますように / 〜ませんように",idText:"semoga ... / mudah-mudahan ..."}],examples:[{jp:"試験に合格しますように。",romaji:"",idText:"Semoga lulus ujian."},{jp:"もう二度と戦争が起きませんように。",romaji:"",idText:"Semoga perang tidak terjadi lagi."}]},{id:"exp-2",grammarId:"gn3-00079",title:"Pola: 〜といいなあ / 〜たらいいなあ",formula:"Vる + といいなあ / Vたら + いいなあ",meaning:"alangkah baiknya kalau ... / andai bisa ...",nuanceNotes:"〜といいなあ / 〜たらいいなあ mengungkapkan harapan atau keinginan yang tidak pasti terwujud, dalam monolog atau percakapan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜といいなあ / 〜たらいいなあ",idText:"alangkah baiknya kalau ... / andai bisa ..."}],examples:[{jp:"明日晴れるといいなあ。",romaji:"",idText:"Alangkah baiknya kalau besok cerah."},{jp:"宝くじが当たったらいいなあ。",romaji:"",idText:"Andai bisa menang lotre."}]},{id:"exp-3",grammarId:"gn3-00135",title:"Pola: 〜てほしい",formula:"V-て + ほしい",meaning:"ingin agar seseorang melakukan ...",nuanceNotes:"〜てほしい menyatakan keinginan pembicara agar orang lain melakukan sesuatu. Berbeda dari 〜たい yang menyatakan keinginan untuk diri sendiri, 〜てほしい ditujukan kepada orang lain. Pola ini cukup langsung dan bisa terasa meminta dengan serius, terutama dalam konteks formal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てほしい",idText:"ingin agar seseorang melakukan ..."}],examples:[{jp:"もっとゆっくり話してほしい。",romaji:"",idText:"Saya ingin agar kamu berbicara lebih pelan."},{jp:"彼に早く来てほしかった。",romaji:"",idText:"Saya ingin dia datang lebih awal (tapi tidak terjadi)."},{jp:"子供には元気に育ってほしい。",romaji:"",idText:"Saya ingin agar anak-anak tumbuh dengan sehat."}]},{id:"exp-4",grammarId:"gn3-00136",title:"Pola: 〜てもらいたい",formula:"V-て + もらいたい",meaning:"ingin meminta seseorang melakukan ... (formal)",nuanceNotes:"〜てもらいたい menyatakan keinginan pembicara untuk menerima tindakan dari orang lain, dengan nuansa bahwa pembicara meminta secara hormat. Merupakan versi yang lebih formal dari 〜てほしい. Dalam situasi yang sangat sopan, digunakan 〜ていただきたい (dengan いただく sebagai versi keigo dari もらう).",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てもらいたい",idText:"ingin meminta seseorang melakukan ... (formal)"}],examples:[{jp:"部長に報告書を確認してもらいたい。",romaji:"",idText:"Saya ingin meminta manajer untuk memeriksa laporan."},{jp:"先生に推薦状を書いてもらいたいと思っています。",romaji:"",idText:"Saya bermaksud meminta guru untuk menulis surat rekomendasi."},{jp:"みなさんに協力してもらいたい。",romaji:"",idText:"Saya ingin meminta semua orang untuk bekerja sama."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "デザート"?',sentencePrompt:'Makna kata "デザート" (デザート) dalam situasi kerja ini adalah:',options:["hidangan penutup, makanan pencuci mulut","pesan lisan, titipan pesan","dan (menyebutkan semua benda tuntas); bersama; dengan; jika / begitu (syarat mutlak/hasil niscaya)","gedung, blok bangunan; kata bantu hitung untuk bangunan/rumah"],correctAnswer:"hidangan penutup, makanan pencuci mulut",explanation:'Makna yang tepat untuk "デザート" adalah "hidangan penutup, makanan pencuci mulut".',diagnosticFeedback:{"pesan lisan, titipan pesan":'Salah: Pilihan "pesan lisan, titipan pesan" adalah makna dari kata "伝言" (でんごん), bukan arti kata "デザート".',"dan (menyebutkan semua benda tuntas); bersama; dengan; jika / begitu (syarat mutlak/hasil niscaya)":'Salah: Pilihan "dan (menyebutkan semua benda tuntas); bersama; dengan; jika / begitu (syarat mutlak/hasil niscaya)" adalah makna dari kata "と" (と), bukan arti kata "デザート".',"gedung, blok bangunan; kata bantu hitung untuk bangunan/rumah":'Salah: Pilihan "gedung, blok bangunan; kata bantu hitung untuk bangunan/rumah" adalah makna dari kata "棟" (とう), bukan arti kata "デザート".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"試験に合格し（　　）。",options:["ますように","といいなあ / 〜たらいいなあ","てほしい","させていただく"],correctAnswer:"ますように",explanation:'Pola 〜ますように / 〜ませんように bermakna "semoga ... / mudah-mudahan ...". Kalimat lengkap: "試験に合格しますように。".',diagnosticFeedback:{"といいなあ / 〜たらいいなあ":'Salah: Pola "といいなあ / 〜たらいいなあ" bermakna "alangkah baiknya kalau ... / andai bisa ...", yang tidak sesuai konteks kalimat ini.',てほしい:'Salah: Pola "てほしい" bermakna "ingin agar seseorang melakukan ...", yang tidak sesuai konteks kalimat ini.',させていただく:'Salah: Pola "させていただく" bermakna "saya mohon izin untuk ..., saya berani ... (keigo rendah hati)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ますように / 〜ませんように secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["もう二度と戦争が起きませんように。","もう二度と戦争が起きませんように。でした","明日晴れるといいなあ。","よく考えたうえで、決断します。"],correctAnswer:"もう二度と戦争が起きませんように。",explanation:'Kalimat yang benar dan alami adalah "もう二度と戦争が起きませんように。" (Semoga perang tidak terjadi lagi.).',diagnosticFeedback:{"もう二度と戦争が起きませんように。でした":"Jebakan Konjugasi: Pola 〜ますように / 〜ませんように membutuhkan aturan sambung (V-ます / V-ません + ように), bukan bentuk ini.","明日晴れるといいなあ。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜といいなあ / 〜たらいいなあ: alangkah baiknya kalau ... / andai bisa ...), bukan kaidah 〜ますように / 〜ませんように.","よく考えたうえで、決断します。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ますように / 〜ませんように secara tepat (semoga ... / mudah-mudahan ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["明日晴 れる とい いなあ。","れる 明日晴 とい いなあ。","明日晴 とい れる いなあ。","いなあ。 明日晴 れる とい"],correctAnswer:"明日晴 れる とい いなあ。",explanation:'Susunan yang benar: "明日晴 れる とい いなあ。" (Alangkah baiknya kalau besok cerah.).',diagnosticFeedback:{"れる 明日晴 とい いなあ。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","明日晴 とい れる いなあ。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","いなあ。 明日晴 れる とい":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["明日晴","れる","とい","いなあ。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional.", saat Sato menyampaikan arahan: 「なるほど。明日晴れるといいなあ。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜ますように / 〜ませんように dan 〜といいなあ / 〜たらいいなあ secara mandiri.",situation:"Situasi komunikasi profesional di Papan pengumuman departemen SDM dan siaran kabar darurat keselamatan kerja operasional.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ますように / 〜ませんように!",modelAnswer:"はい、Satoさん！ 試験に合格しますように。。",modelAnswerId:"Ya, Sato! Semoga lulus ujian..",culturalEtiquette:"Selalu sebutkan sumber informasi awal saat meneruskan kabar agar tidak menimbulkan rumor kerja.",skillUnlocked:["Menguasai formulasi pola 〜ますように / 〜ませんように","Mampu menerapkan prinsip koordinasi komunikasi kerja Laporan Wacana, Kutipan Berita & Informasi Resmi"]},pocket_summary:{keyFormula:"〜ますように / 〜ませんように (semoga ... / mudah-mudahan ...)",coreWords:["デザート【デザート】 (hidangan penutup, makanan pencuci mulut)","伝言【でんごん】 (pesan lisan, titipan pesan)","と【と】 (dan (menyebutkan semua benda tuntas); bersama; dengan; jika / begitu (syarat mutlak/hasil niscaya))","棟【とう】 (gedung, blok bangunan; kata bantu hitung untuk bangunan/rumah)"],coreWarning:"Jangan menggunakan ragam kasual 〜datte saat menyampaikan pengumuman resmi dari direksi.",quickDialogue:"A: ブディさん、デザートの 状況【じょうきょう】は ど... → B: はい、Satoさん！ 試験に合格しますように。。..."}}},r={"les-n3-u20-01":{pedagogical_framework:{what:{summary:"Keigo Bisnis Lanjut, Negosiasi & Komunikasi Korporat (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜させていただく, 〜ていただきたい, 〜ことを願っている, 〜ことを期待している, 〜ことを祈っている dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜させていただく dan 〜ていただきたい dalam percakapan kerja wajar.",targetPatterns:["〜させていただく (saya mohon izin untuk ..., saya berani ... (keigo rendah hati))","〜ていただきたい (saya ingin agar Anda ..., saya mohon agar Anda ... (formal/tertulis))","〜ことを願っている (berharap bahwa ..., mendoakan agar ...)","〜ことを期待している (mengharapkan bahwa ..., berharap ... (dengan ekspektasi))","〜ことを祈っている (mendoakan agar ..., berdoa supaya ...)"],coreVocabSample:["から","かわ","かわ","かわ","きかい","きみ","きゅう","きゅう"]},sensei_context:{sceneIntro:"Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜させていただく dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Keigo Bisnis Lanjut, Negosiasi & Komunikasi Korporat",etiquette:"Terapkan postur duduk tegak, kedua tangan di atas paha, dan pertahankan kontak mata empatik santun.",taboos:"Jangan pernah memakai bentuk Sonkeigo (penghormatan) untuk tindakan diri sendiri atau anggota perusahaan sendiri."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜させていただく",moraNote:"Ucapkan mō-shi-a-ge-ma-su dengan vokal o panjang yang anggun dan santun.",soundTip:"Ucapkan 〜させていただく dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜させていただく",caseScenario:"Menggunakan 〜させていただく tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜させていただく.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜させていただく sesuai kaidah.",explanation:"Kaidah koneksi 〜させていただく: V-stem (causative させ) + ていただく."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Keigo Bisnis Lanjut, Negosiasi & Komunikasi Korporat (Fondasi & Pemahaman Pola)",setting:"Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri.",narrative:"Budi dan Sato berkoordinasi mengenai alur operasional kerja menggunakan pola 〜させていただく."}},dialogue:[{id:"d1",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"ブディさん、空の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、空の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, kara no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai kekosongan; menjadi kosong? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Satoさん！ 本日は早退させていただきます。。",furigana:"はい、Satoさん！ 本日は早退させていただきます。。",romaji:"Hai, Sato-san! させていただく de susumete imasu.",idText:"Ya, Sato! Dengan izin, saya hari ini pulang lebih awal.."},{id:"d3",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"なるほど。ぜひご参加いただきたいと思います。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。ぜひご参加いただきたいと思います。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Saya benar-benar berharap Anda sudi berpartisipasi.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02487",word:"空",reading:"から",romaji:"kara",meaning:"kekosongan; menjadi kosong",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"空【から】を 確認【かくにん】します。",furigana:"空を 確認します。",romaji:"kara o kakunin shimasu.",idText:"Memeriksa kekosongan; menjadi kosong."}},{id:"vg-n3-02488",word:"河",reading:"かわ",romaji:"kawa",meaning:"sungai",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"河【かわ】を 確認【かくにん】します。",furigana:"河を 確認します。",romaji:"kawa o kakunin shimasu.",idText:"Memeriksa sungai."}},{id:"vg-n3-02489",word:"革",reading:"かわ",romaji:"kawa",meaning:"kulit",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"革【かわ】を 確認【かくにん】します。",furigana:"革を 確認します。",romaji:"kawa o kakunin shimasu.",idText:"Memeriksa kulit."}},{id:"vg-n3-02490",word:"皮",reading:"かわ",romaji:"kawa",meaning:"skin; hide",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"皮【かわ】を 確認【かくにん】します。",furigana:"皮を 確認します。",romaji:"kawa o kakunin shimasu.",idText:"Memeriksa skin; hide."}},{id:"vg-n3-02494",word:"機械",reading:"きかい",romaji:"kikai",meaning:"mesin; mekanisme",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"機械【きかい】を 確認【かくにん】します。",furigana:"機械を 確認します。",romaji:"kikai o kakunin shimasu.",idText:"Memeriksa mesin; mekanisme."}},{id:"vg-n3-02497",word:"気味",reading:"きみ",romaji:"kimi",meaning:"sensasi; perasaan",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"気味【きみ】を 確認【かくにん】します。",furigana:"気味を 確認します。",romaji:"kimi o kakunin shimasu.",idText:"Memeriksa sensasi; perasaan."}},{id:"vg-n3-02498",word:"級",reading:"きゅう",romaji:"kyuu",meaning:"class; grade",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"級【きゅう】を 確認【かくにん】します。",furigana:"級を 確認します。",romaji:"kyuu o kakunin shimasu.",idText:"Memeriksa class; grade."}},{id:"vg-n3-02499",word:"旧",reading:"きゅう",romaji:"kyuu",meaning:"mantan-",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"旧【きゅう】を 確認【かくにん】します。",furigana:"旧を 確認します。",romaji:"kyuu o kakunin shimasu.",idText:"Memeriksa mantan-."}}],explanations:[{id:"exp-1",grammarId:"gn3-00155",title:"Pola: 〜させていただく",formula:"V-stem (causative させ) + ていただく",meaning:"saya mohon izin untuk ..., saya berani ... (keigo rendah hati)",nuanceNotes:'〜させていただく adalah pola keigo yang sangat umum dalam konteks bisnis dan formal. Secara harfiah berarti "saya dengan rendah hati menerima izin untuk melakukan X". Menggabungkan bentuk kausatif (〜させる) dengan kata kerja rendah hati いただく, sehingga pembicara seolah meminta restu untuk bertindak. Dipakai untuk memberitahu tindakan pembicara dengan nada sopan.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜させていただく",idText:"saya mohon izin untuk ..., saya berani ... (keigo rendah hati)"}],examples:[{jp:"本日は早退させていただきます。",romaji:"",idText:"Dengan izin, saya hari ini pulang lebih awal."},{jp:"確認しさせていただいたうえで、ご連絡いたします。",romaji:"",idText:"Setelah saya periksa dengan seksama, akan saya hubungi Anda."},{jp:"発表させていただきます。",romaji:"",idText:"Izinkan saya menyampaikan presentasi ini."}]},{id:"exp-2",grammarId:"gn3-00159",title:"Pola: 〜ていただきたい",formula:"V-て + いただきたい",meaning:"saya ingin agar Anda ..., saya mohon agar Anda ... (formal/tertulis)",nuanceNotes:'〜ていただきたい menyatakan keinginan atau harapan pembicara agar lawan bicara melakukan sesuatu, dengan nada sangat formal dan sopan. Menggabungkan いただく (rendah hati) dengan 〜たい (ingin), pola ini sering ditemukan dalam surat resmi, pengumuman, atau pidato. Berbeda dari permohonan langsung, pola ini lebih menyampaikan "harapan" pembicara.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ていただきたい",idText:"saya ingin agar Anda ..., saya mohon agar Anda ... (formal/tertulis)"}],examples:[{jp:"ぜひご参加いただきたいと思います。",romaji:"",idText:"Saya benar-benar berharap Anda sudi berpartisipasi."},{jp:"期限までにご提出いただきたい。",romaji:"",idText:"Saya mohon agar Anda menyerahkannya sebelum batas waktu."},{jp:"詳細はこちらをご確認いただきたい。",romaji:"",idText:"Saya ingin agar Anda mengonfirmasi detailnya di sini."}]},{id:"exp-3",grammarId:"gn3-00160",title:"Pola: 〜ことを願っている",formula:"V-dict / N + であること + を願っている",meaning:"berharap bahwa ..., mendoakan agar ...",nuanceNotes:'〜ことを願っている menyatakan harapan yang sungguh-sungguh dan mendalam dari pembicara terhadap suatu keadaan atau kejadian. 願う berarti "berharap/menginginkan dengan tulus" dan sering mengandung nuansa doa atau kerinduan. Digunakan dalam konteks formal maupun emosional untuk menyampaikan harapan yang penting bagi pembicara.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことを願っている",idText:"berharap bahwa ..., mendoakan agar ..."}],examples:[{jp:"あなたが幸せになることを願っています。",romaji:"",idText:"Saya berharap kamu bisa bahagia."},{jp:"両国の関係が改善されることを願っている。",romaji:"",idText:"Kami berharap hubungan kedua negara bisa membaik."},{jp:"早く回復することを願っています。",romaji:"",idText:"Kami mendoakan agar kamu cepat pulih."}]},{id:"exp-4",grammarId:"gn3-00161",title:"Pola: 〜ことを期待している",formula:"V-dict / N + であること + を期待している",meaning:"mengharapkan bahwa ..., berharap ... (dengan ekspektasi)",nuanceNotes:'〜ことを期待している menyatakan ekspektasi atau harapan berdasarkan pertimbangan rasional — pembicara "mengharapkan" sesuatu karena ada alasan atau dasar untuk itu. 期待する mengandung makna "berharap sambil menantikan dengan optimis". Berbeda dari 願う yang lebih emosional, 期待する lebih terkait dengan kepercayaan terhadap kemampuan atau situasi.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことを期待している",idText:"mengharapkan bahwa ..., berharap ... (dengan ekspektasi)"}],examples:[{jp:"君の成長を期待しているよ。",romaji:"",idText:"Aku berharap (dan percaya) kamu akan berkembang."},{jp:"交渉がうまくいくことを期待している。",romaji:"",idText:"Kami berharap negosiasi ini berjalan dengan baik."},{jp:"新しいシステムが効果を発揮することを期待している。",romaji:"",idText:"Kami mengharapkan sistem baru ini menunjukkan hasilnya."}]},{id:"exp-5",grammarId:"gn3-00162",title:"Pola: 〜ことを祈っている",formula:"V-dict / N + であること + を祈っている",meaning:"mendoakan agar ..., berdoa supaya ...",nuanceNotes:'〜ことを祈っている menyatakan harapan yang sangat tulus, sering kali dengan nuansa doa atau permohonan sungguh-sungguh. 祈る secara harfiah berarti "berdoa" dan mengandung intensitas harapan yang lebih kuat dibandingkan 願う. Digunakan saat pembicara benar-benar menginginkan sesuatu dan terkesan "menyerahkannya kepada takdir atau Yang Maha Kuasa".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことを祈っている",idText:"mendoakan agar ..., berdoa supaya ..."}],examples:[{jp:"ご無事でいられることを祈っています。",romaji:"",idText:"Kami mendoakan agar Anda selalu selamat."},{jp:"試験に合格することを祈っているよ。",romaji:"",idText:"Aku berdoa agar kamu lulus ujian ya."},{jp:"世界が平和になることを祈っています。",romaji:"",idText:"Kami mendoakan agar dunia ini damai."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "空"?',sentencePrompt:'Makna kata "空" (から) dalam situasi kerja ini adalah:',options:["kekosongan; menjadi kosong","sungai","kulit","skin; hide"],correctAnswer:"kekosongan; menjadi kosong",explanation:'Makna yang tepat untuk "空" adalah "kekosongan; menjadi kosong".',diagnosticFeedback:{sungai:'Salah: Pilihan "sungai" adalah makna dari kata "河" (かわ), bukan arti kata "空".',kulit:'Salah: Pilihan "kulit" adalah makna dari kata "革" (かわ), bukan arti kata "空".',"skin; hide":'Salah: Pilihan "skin; hide" adalah makna dari kata "皮" (かわ), bukan arti kata "空".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"本日は早退（　　）。",options:["させていただきます","ていただきたい","ことを願っている","うちに"],correctAnswer:"させていただきます",explanation:'Pola 〜させていただく bermakna "saya mohon izin untuk ..., saya berani ... (keigo rendah hati)". Kalimat lengkap: "本日は早退させていただきます。".',diagnosticFeedback:{ていただきたい:'Salah: Pola "ていただきたい" bermakna "saya ingin agar Anda ..., saya mohon agar Anda ... (formal/tertulis)", yang tidak sesuai konteks kalimat ini.',ことを願っている:'Salah: Pola "ことを願っている" bermakna "berharap bahwa ..., mendoakan agar ...", yang tidak sesuai konteks kalimat ini.',うちに:'Salah: Pola "うちに" bermakna "sementara masih ... / selagi ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜させていただく secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["確認しさせていただいたうえで、ご連絡いたします。","確認しさせていただいたうえで、ご連絡いたします。でした","ぜひご参加いただきたいと思います。","黒板に予定が書いてある。"],correctAnswer:"確認しさせていただいたうえで、ご連絡いたします。",explanation:'Kalimat yang benar dan alami adalah "確認しさせていただいたうえで、ご連絡いたします。" (Setelah saya periksa dengan seksama, akan saya hubungi Anda.).',diagnosticFeedback:{"確認しさせていただいたうえで、ご連絡いたします。でした":"Jebakan Konjugasi: Pola 〜させていただく membutuhkan aturan sambung (V-stem (causative させ) + ていただく), bukan bentuk ini.","ぜひご参加いただきたいと思います。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ていただきたい: saya ingin agar Anda ..., saya mohon agar Anda ... (formal/tertulis)), bukan kaidah 〜させていただく.","黒板に予定が書いてある。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜させていただく secara tepat (saya mohon izin untuk ..., saya berani ... (keigo rendah hati))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["ぜひご 参加いた だきたい と思います。","参加いた ぜひご だきたい と思います。","ぜひご だきたい 参加いた と思います。","と思います。 ぜひご 参加いた だきたい"],correctAnswer:"ぜひご 参加いた だきたい と思います。",explanation:'Susunan yang benar: "ぜひご 参加いた だきたい と思います。" (Saya benar-benar berharap Anda sudi berpartisipasi.).',diagnosticFeedback:{"参加いた ぜひご だきたい と思います。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","ぜひご だきたい 参加いた と思います。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","と思います。 ぜひご 参加いた だきたい":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["ぜひご","参加いた","だきたい","と思います。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri.", saat Sato menyampaikan arahan: 「なるほど。ぜひご参加いただきたいと思います。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜させていただく dan 〜ていただきたい dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜させていただく!",modelAnswer:"はい、Satoさん！ 本日は早退させていただきます。。",modelAnswerId:"Ya, Sato! Dengan izin, saya hari ini pulang lebih awal..",culturalEtiquette:"Terapkan postur duduk tegak, kedua tangan di atas paha, dan pertahankan kontak mata empatik santun.",skillUnlocked:["Menguasai formulasi pola 〜させていただく","Mampu menerapkan prinsip koordinasi komunikasi kerja Keigo Bisnis Lanjut, Negosiasi & Komunikasi Korporat"]},pocket_summary:{keyFormula:"〜させていただく (saya mohon izin untuk ..., saya berani ... (keigo rendah hati))",coreWords:["空【から】 (kekosongan; menjadi kosong)","河【かわ】 (sungai)","革【かわ】 (kulit)","皮【かわ】 (skin; hide)"],coreWarning:"Jangan pernah memakai bentuk Sonkeigo (penghormatan) untuk tindakan diri sendiri atau anggota perusahaan sendiri.",quickDialogue:"A: ブディさん、空の 状況【じょうきょう】は どうです... → B: はい、Satoさん！ 本日は早退させていただきます..."}},"les-n3-u20-02":{pedagogical_framework:{what:{summary:"Keigo Bisnis Lanjut, Negosiasi & Komunikasi Korporat (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜といいのに, 〜を通して, 〜として, 〜ことになる dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜といいのに dan 〜を通して secara mandiri.",targetPatterns:["〜といいのに (kalau saja ..., seandainya saja ... (harapan bertentangan dengan kenyataan sekarang))","〜を通して (melalui ..., lewat ... (proses panjang))","〜として (sebagai ..., dalam kapasitas sebagai ...)","〜ことになる (ternyata menjadi ..., sudah diputuskan bahwa ...)"],coreVocabSample:["とおり","とき","どよう","どんな","ないよう","なか","なに","にちよう"]},sensei_context:{sceneIntro:"Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜といいのに dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Keigo Bisnis Lanjut, Negosiasi & Komunikasi Korporat",etiquette:"Terapkan postur duduk tegak, kedua tangan di atas paha, dan pertahankan kontak mata empatik santun.",taboos:"Jangan pernah memakai bentuk Sonkeigo (penghormatan) untuk tindakan diri sendiri atau anggota perusahaan sendiri."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜といいのに",moraNote:"Ucapkan mō-shi-a-ge-ma-su dengan vokal o panjang yang anggun dan santun.",soundTip:"Ucapkan 〜といいのに dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜といいのに",caseScenario:"Menggunakan 〜といいのに tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜といいのに.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜といいのに sesuai kaidah.",explanation:"Kaidah koneksi 〜といいのに: V-dict / い-Adj / な-Adj (な) + といいのに."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Keigo Bisnis Lanjut, Negosiasi & Komunikasi Korporat (Produksi Aktif & Aplikasi Nyata)",setting:"Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri.",narrative:"Budi dan Sato berkoordinasi mengenai alur operasional kerja menggunakan pola 〜といいのに."}},dialogue:[{id:"d1",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"ブディさん、通りの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、通りの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, toori no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai in accordance with ~; following ~? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Satoさん！ 明日、晴れるといいのになあ。。",furigana:"はい、Satoさん！ 明日、晴れるといいのになあ。。",romaji:"Hai, Sato-san! といいのに de susumete imasu.",idText:"Ya, Sato! Kalau saja besok cerah ya.."},{id:"d3",speaker:"Sato",speakerRole:"Direktur Kemitraan",avatar:"👔",jp:"なるほど。読書を通して、多くのことを学んだ。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。読書を通して、多くのことを学んだ。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Melalui membaca, saya belajar banyak hal.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02588",word:"通り",reading:"とおり",romaji:"toori",meaning:"in accordance with ~; following ~",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"通り【とおり】を 確認【かくにん】します。",furigana:"通りを 確認します。",romaji:"toori o kakunin shimasu.",idText:"Memeriksa in accordance with ~; following ~."}},{id:"vg-n3-02589",word:"時",reading:"とき",romaji:"toki",meaning:"time; hour",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"時【とき】を 確認【かくにん】します。",furigana:"時を 確認します。",romaji:"toki o kakunin shimasu.",idText:"Memeriksa time; hour."}},{id:"vg-n3-02592",word:"土曜",reading:"どよう",romaji:"doyou",meaning:"Sabtu",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"土曜【どよう】を 確認【かくにん】します。",furigana:"土曜を 確認します。",romaji:"doyou o kakunin shimasu.",idText:"Memeriksa Sabtu."}},{id:"vg-n3-02593",word:"どんな",reading:"どんな",romaji:"donna",meaning:"apa; jenis apa",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"どんなを 確認【かくにん】します。",furigana:"どんなを 確認します。",romaji:"donna o kakunin shimasu.",idText:"Memeriksa apa; jenis apa."}},{id:"vg-n3-02594",word:"内容",reading:"ないよう",romaji:"naiyou",meaning:"subject; contents",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"内容【ないよう】を 確認【かくにん】します。",furigana:"内容を 確認します。",romaji:"naiyou o kakunin shimasu.",idText:"Memeriksa subject; contents."}},{id:"vg-n3-02596",word:"仲",reading:"なか",romaji:"naka",meaning:"hubungan",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"仲【なか】を 確認【かくにん】します。",furigana:"仲を 確認します。",romaji:"naka o kakunin shimasu.",idText:"Memeriksa hubungan."}},{id:"vg-n3-02597",word:"何",reading:"なに",romaji:"nani",meaning:"apa",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"何【なに】を 確認【かくにん】します。",furigana:"何を 確認します。",romaji:"nani o kakunin shimasu.",idText:"Memeriksa apa."}},{id:"vg-n3-02598",word:"日曜",reading:"にちよう",romaji:"nichiyou",meaning:"Minggu",pos:"noun",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"日曜【にちよう】を 確認【かくにん】します。",furigana:"日曜を 確認します。",romaji:"nichiyou o kakunin shimasu.",idText:"Memeriksa Minggu."}}],explanations:[{id:"exp-1",grammarId:"gn3-00167",title:"Pola: 〜といいのに",formula:"V-dict / い-Adj / な-Adj (な) + といいのに",meaning:"kalau saja ..., seandainya saja ... (harapan bertentangan dengan kenyataan sekarang)",nuanceNotes:"〜といいのに menyatakan harapan yang bertentangan dengan kenyataan saat ini atau yang kemungkinan tidak terpenuhi. Pola ini mengandung nuansa kekecewaan ringan atau kerinduan — pembicara tahu bahwa kondisi tidak ideal, namun berharap seandainya berbeda. のに di akhir memberikan nuansa kontras dengan kenyataan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜といいのに",idText:"kalau saja ..., seandainya saja ... (harapan bertentangan dengan kenyataan sekarang)"}],examples:[{jp:"明日、晴れるといいのになあ。",romaji:"",idText:"Kalau saja besok cerah ya."},{jp:"もっと時間があるといいのに。",romaji:"",idText:"Seandainya saja aku punya lebih banyak waktu."},{jp:"彼が来てくれるといいのになあ。",romaji:"",idText:"Kalau saja dia mau datang ya."}]},{id:"exp-2",grammarId:"gn3-00141",title:"Pola: 〜を通して",formula:"N + を通して / を通じて",meaning:"melalui ..., lewat ... (proses panjang)",nuanceNotes:'〜を通して menyatakan bahwa sesuatu terjadi atau tercapai melalui suatu media, perantara, atau proses tertentu. Bisa juga berarti "sepanjang" dalam konteks waktu (例: 一年を通して = sepanjang tahun). Bentuk 〜を通じて memiliki makna yang hampir sama dan sering dapat dipertukarkan.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜を通して",idText:"melalui ..., lewat ... (proses panjang)"}],examples:[{jp:"読書を通して、多くのことを学んだ。",romaji:"",idText:"Melalui membaca, saya belajar banyak hal."},{jp:"交流プログラムを通して、友達ができた。",romaji:"",idText:"Melalui program pertukaran, saya mendapat teman."},{jp:"一年を通して、この地域は温暖な気候だ。",romaji:"",idText:"Sepanjang tahun, daerah ini beriklim hangat."}]},{id:"exp-3",grammarId:"gn3-00144",title:"Pola: 〜として",formula:"N + として",meaning:"sebagai ..., dalam kapasitas sebagai ...",nuanceNotes:'〜として menyatakan posisi, peran, kapasitas, atau status seseorang atau sesuatu. Dapat juga berarti "sebagai" dalam konteks menganggap sesuatu dengan cara tertentu. Pola ini sangat serbaguna dan umum digunakan dalam konteks formal maupun informal.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜として",idText:"sebagai ..., dalam kapasitas sebagai ..."}],examples:[{jp:"彼は医者として、多くの患者を救った。",romaji:"",idText:"Sebagai dokter, dia menyelamatkan banyak pasien."},{jp:"これは問題として取り上げるべきだ。",romaji:"",idText:"Ini harus diangkat sebagai suatu masalah."},{jp:"留学生として、日本の文化を学んでいる。",romaji:"",idText:"Sebagai mahasiswa pertukaran, saya sedang mempelajari budaya Jepang."}]},{id:"exp-4",grammarId:"gn3-00122",title:"Pola: 〜ことになる",formula:"V-plain (非過去) + ことになる",meaning:"ternyata menjadi ..., sudah diputuskan bahwa ...",nuanceNotes:"〜ことになる menyatakan suatu keputusan atau hasil yang terjadi dari luar kehendak pembicara, misalnya keputusan organisasi, atasan, atau keadaan yang berkembang secara alami. Sering digunakan untuk mengumumkan perubahan situasi secara sopan tanpa menekankan kehendak pribadi. Bentuk 〜ことになっている dibahas terpisah pada pola berikutnya.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことになる",idText:"ternyata menjadi ..., sudah diputuskan bahwa ..."}],examples:[{jp:"来月から大阪に転勤することになった。",romaji:"",idText:"Sudah diputuskan bahwa saya akan pindah tugas ke Osaka mulai bulan depan."},{jp:"彼女が新しいプロジェクトを担当することになった。",romaji:"",idText:"Ternyata dialah yang akan menangani proyek baru itu."},{jp:"事情があって、パーティーに行けないことになった。",romaji:"",idText:"Karena suatu keadaan, ternyata saya tidak bisa pergi ke pesta."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "通り"?',sentencePrompt:'Makna kata "通り" (とおり) dalam situasi kerja ini adalah:',options:["in accordance with ~; following ~","time; hour","Sabtu","apa; jenis apa"],correctAnswer:"in accordance with ~; following ~",explanation:'Makna yang tepat untuk "通り" adalah "in accordance with ~; following ~".',diagnosticFeedback:{"time; hour":'Salah: Pilihan "time; hour" adalah makna dari kata "時" (とき), bukan arti kata "通り".',Sabtu:'Salah: Pilihan "Sabtu" adalah makna dari kata "土曜" (どよう), bukan arti kata "通り".',"apa; jenis apa":'Salah: Pilihan "apa; jenis apa" adalah makna dari kata "どんな" (どんな), bukan arti kata "通り".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"明日、晴れる（　　）なあ。",options:["といいのに","を通して","として","うちに"],correctAnswer:"といいのに",explanation:'Pola 〜といいのに bermakna "kalau saja ..., seandainya saja ... (harapan bertentangan dengan kenyataan sekarang)". Kalimat lengkap: "明日、晴れるといいのになあ。".',diagnosticFeedback:{を通して:'Salah: Pola "を通して" bermakna "melalui ..., lewat ... (proses panjang)", yang tidak sesuai konteks kalimat ini.',として:'Salah: Pola "として" bermakna "sebagai ..., dalam kapasitas sebagai ...", yang tidak sesuai konteks kalimat ini.',うちに:'Salah: Pola "うちに" bermakna "sementara masih ... / selagi ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜といいのに secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["もっと時間があるといいのに。","もっと時間があるといいのにでした。","読書を通して、多くのことを学んだ。","黒板に予定が書いてある。"],correctAnswer:"もっと時間があるといいのに。",explanation:'Kalimat yang benar dan alami adalah "もっと時間があるといいのに。" (Seandainya saja aku punya lebih banyak waktu.).',diagnosticFeedback:{"もっと時間があるといいのにでした。":"Jebakan Konjugasi: Pola 〜といいのに membutuhkan aturan sambung (V-dict / い-Adj / な-Adj (な) + といいのに), bukan bentuk ini.","読書を通して、多くのことを学んだ。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜を通して: melalui ..., lewat ... (proses panjang)), bukan kaidah 〜といいのに.","黒板に予定が書いてある。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜といいのに secara tepat (kalau saja ..., seandainya saja ... (harapan bertentangan dengan kenyataan sekarang))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["読書を 通して、 多くのことを 学んだ。","通して、 読書を 多くのことを 学んだ。","読書を 多くのことを 通して、 学んだ。","学んだ。 読書を 通して、 多くのことを"],correctAnswer:"読書を 通して、 多くのことを 学んだ。",explanation:'Susunan yang benar: "読書を 通して、 多くのことを 学んだ。" (Melalui membaca, saya belajar banyak hal.).',diagnosticFeedback:{"通して、 読書を 多くのことを 学んだ。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","読書を 多くのことを 通して、 学んだ。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","学んだ。 読書を 通して、 多くのことを":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["読書を","通して、","多くのことを","学んだ。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri.", saat Sato menyampaikan arahan: 「なるほど。読書を通して、多くのことを学んだ。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜といいのに dan 〜を通して secara mandiri.",situation:"Situasi komunikasi profesional di Ruang tamu eksekutif kantor pusat saat penandatanganan nota kesepahaman (MoU) kemitraan industri.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜といいのに!",modelAnswer:"はい、Satoさん！ 明日、晴れるといいのになあ。。",modelAnswerId:"Ya, Sato! Kalau saja besok cerah ya..",culturalEtiquette:"Terapkan postur duduk tegak, kedua tangan di atas paha, dan pertahankan kontak mata empatik santun.",skillUnlocked:["Menguasai formulasi pola 〜といいのに","Mampu menerapkan prinsip koordinasi komunikasi kerja Keigo Bisnis Lanjut, Negosiasi & Komunikasi Korporat"]},pocket_summary:{keyFormula:"〜といいのに (kalau saja ..., seandainya saja ... (harapan bertentangan dengan kenyataan sekarang))",coreWords:["通り【とおり】 (in accordance with ~; following ~)","時【とき】 (time; hour)","土曜【どよう】 (Sabtu)","どんな【どんな】 (apa; jenis apa)"],coreWarning:"Jangan pernah memakai bentuk Sonkeigo (penghormatan) untuk tindakan diri sendiri atau anggota perusahaan sendiri.",quickDialogue:"A: ブディさん、通りの 状況【じょうきょう】は どうで... → B: はい、Satoさん！ 明日、晴れるといいのになあ。..."}}};export{t as a,i as b,e as c,n as d,a as e,r as u};
